function acReady():bool {try{return (bool)q("SHOW TABLES LIKE 'ac_curriculum'")->fetchColumn();}catch(Throwable $e){return false;}}
function acInstall():void {global $pdo;foreach([
"CREATE TABLE IF NOT EXISTS ac_curriculum(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,session_name VARCHAR(100) NOT NULL,term_name VARCHAR(70) NOT NULL,topic VARCHAR(220) NOT NULL,objectives TEXT NULL,week_no INT NOT NULL DEFAULT 1,coverage ENUM('planned','in_progress','completed') NOT NULL DEFAULT 'planned',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,class_id,subject_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
