function acField(string $k,int $n=220):string{return mb_substr(trim((string)($_POST[$k]??'')),0,$n);}
function acOwn(string $table,int $tid,int $id):bool {if(!in_array($table,['classes','subjects','students','users','ac_curriculum','ac_assessments','ac_scores'],true))return false;return (bool)g("SELECT id FROM `$table` WHERE tenant_id=? AND id=?",[$tid,$id]);}
function acGrade(float $p):string{return grade($p);}
function acPublished(int $tid,int $class,string $session,string $term):bool {return (bool)g("SELECT id FROM ac_term_approvals WHERE tenant_id=? AND class_id=? AND session_name=? AND term_name=? AND status='published'",[$tid,$class,$session,$term]);}
function acAllocated(int $tid,int $teacher,int $class,int $subject,string $session):bool{return (bool)g('SELECT id FROM ac_allocations WHERE tenant_id=? AND teacher_id=? AND class_id=? AND subject_id=? AND session_name=?',[$tid,$teacher,$class,$subject,$session]);}
function acValidatePublication(int $tid,int $class,string $session,string $term):void {
 $ass=q('SELECT id,subject_id,weight FROM ac_assessments WHERE tenant_id=? AND class_id=? AND session_name=? AND term_name=?',[$tid,$class,$session,$term])->fetchAll();if(!$ass)throw new RuntimeException('Create assessments before publishing.');
 $weights=[];foreach($ass as $a)$weights[$a['subject_id']]=($weights[$a['subject_id']]??0)+(float)$a['weight'];foreach($weights as $w)if(abs($w-100)>0.01)throw new RuntimeException('Every assessed subject must have exactly 100% weighting.');
 $students=q('SELECT id FROM students WHERE tenant_id=? AND class_id=?',[$tid,$class])->fetchAll();if(!$students)throw new RuntimeException('No enrolled students in this class.');
 $missing=(int)g("SELECT COUNT(*) FROM students st CROSS JOIN ac_assessments a LEFT JOIN ac_scores sc ON sc.tenant_id=a.tenant_id AND sc.assessment_id=a.id AND sc.student_id=st.id WHERE st.tenant_id=? AND st.class_id=? AND a.tenant_id=? AND a.class_id=? AND a.session_name=? AND a.term_name=? AND (sc.id IS NULL OR sc.status<>'approved')",[$tid,$class,$tid,$class,$session,$term]);
 if($missing)throw new RuntimeException($missing.' assessment entries are missing or unapproved. Complete all student scores before publishing.');
}
function acPdf(string $filename,array $lines):void {
 $escape=static fn($v)=>str_replace(['\\','(',')',"\r","\n"],['\\\\','\\(','\\)',' ',' '],(string)$v);
 $pages=array_chunk($lines,45);if(!$pages)$pages=[['No records available']];$objects=[];$add=static function($obj)use(&$objects){$objects[]=$obj;return count($objects);};
 $catalog=$add('');$pagesId=$add('');$font=$add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');$kids=[];
 foreach($pages as $pageLines){$stream="BT /F1 11 Tf 48 792 Td 15 TL ";foreach($pageLines as $line){$stream.='('.$escape(iconv('UTF-8','Windows-1252//TRANSLIT//IGNORE',(string)$line)?:' ').") Tj T* ";}$stream.='ET';$content=$add('<< /Length '.strlen($stream).' >>' ."\nstream\n".$stream."\nendstream");$pid=$add('<< /Type /Page /Parent '.$pagesId.' 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 '.$font.' 0 R >> >> /Contents '.$content.' 0 R >>');$kids[]=$pid.' 0 R';}
 $objects[$catalog-1]='<< /Type /Catalog /Pages '.$pagesId.' 0 R >>';$objects[$pagesId-1]='<< /Type /Pages /Kids ['.implode(' ',$kids).'] /Count '.count($kids).' >>';$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $i=>$o){$offsets[]=strlen($pdf);$pdf.=($i+1)." 0 obj\n".$o."\nendobj\n";}$xref=strlen($pdf);$pdf.="xref\n0 ".(count($objects)+1)."\n0000000000 65535 f \n";foreach(array_slice($offsets,1) as $off)$pdf.=sprintf('%010d 00000 n ', $off)."\n";$pdf.="trailer << /Size ".(count($objects)+1).' /Root '.$catalog." 0 R >>\nstartxref\n".$xref."\n%%EOF";
 header('Content-Type:application/pdf');header('Content-Disposition:attachment; filename="'.preg_replace('/[^a-zA-Z0-9_.-]/','_',$filename).'"');header('Content-Length:'.strlen($pdf));echo $pdf;exit;
}

function acTermResults(int $tid,int $class,string $session,string $term,bool $publishedOnly=false):array {
 $sql="SELECT sc.student_id,st.name student_name,ass.subject_id,su.name subject_name, SUM(sc.score/ass.max_score*ass.weight) total, SUM(ass.weight) possible,MIN(sc.status='approved') all_approved FROM ac_scores sc JOIN ac_assessments ass ON ass.id=sc.assessment_id AND ass.tenant_id=sc.tenant_id JOIN students st ON st.id=sc.student_id AND st.tenant_id=sc.tenant_id JOIN subjects su ON su.id=ass.subject_id AND su.tenant_id=sc.tenant_id WHERE sc.tenant_id=? AND ass.class_id=? AND ass.session_name=? AND ass.term_name=? GROUP BY sc.student_id,st.name,ass.subject_id,su.name ORDER BY st.name,su.name";
 $rows=q($sql,[$tid,$class,$session,$term])->fetchAll();if($publishedOnly)$rows=array_values(array_filter($rows,fn($r)=>(int)$r['all_approved']===1));return $rows;
}

function acClassRankings(int $tid,int $class,string $session,string $term):array {
 $rows=acTermResults($tid,$class,$session,$term,true);$by=[];
 foreach($rows as $r){$id=(int)$r['student_id'];if(!isset($by[$id]))$by[$id]=['student_id'=>$id,'name'=>$r['student_name'],'sum'=>0.0,'subjects'=>0];$by[$id]['sum']+=(float)$r['total'];$by[$id]['subjects']++;}
 foreach($by as &$r)$r['average']=$r['subjects']?round($r['sum']/$r['subjects'],2):0;unset($r);
 usort($by,fn($a,$b)=>($b['average']<=>$a['average'])?:strcmp($a['name'],$b['name']));$position=0;$last=null;
 foreach($by as $i=>&$r){if($last===null||$r['average']!==$last)$position=$i+1;$r['rank']=$position;$last=$r['average'];}unset($r);return $by;
}
