 ,"CREATE TABLE IF NOT EXISTS crm_answers(tenant_id BIGINT UNSIGNED NOT NULL,application_id BIGINT UNSIGNED NOT NULL,answers_json MEDIUMTEXT NOT NULL,PRIMARY KEY(tenant_id,application_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ,"CREATE TABLE IF NOT EXISTS crm_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,question TEXT NOT NULL,option_a VARCHAR(500) NOT NULL,option_b VARCHAR(500) NOT NULL,option_c VARCHAR(500) NOT NULL,option_d VARCHAR(500) NOT NULL,correct CHAR(1) NOT NULL,points INT NOT NULL DEFAULT 1,active TINYINT NOT NULL DEFAULT 1,INDEX(tenant_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ,"CREATE TABLE IF NOT EXISTS crm_cbt_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,application_id BIGINT UNSIGNED NOT NULL,access_token CHAR(64) NOT NULL UNIQUE,started_at DATETIME NULL,submitted_at DATETIME NULL,expires_at DATETIME NULL,answers_json MEDIUMTEXT NULL,score DECIMAL(6,2) NULL,UNIQUE KEY uq_crm_attempt(tenant_id,application_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ,"CREATE TABLE IF NOT EXISTS crm_messages(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,application_id BIGINT UNSIGNED NOT NULL,recipient VARCHAR(190) NOT NULL,subject VARCHAR(180) NOT NULL,body TEXT NOT NULL,status VARCHAR(25) NOT NULL DEFAULT 'queued',sent_at DATETIME NULL,error_text VARCHAR(250) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
