 $schoolName=trim((string)($_POST['school_name']??''));
 $adminName=trim((string)($_POST['school_admin_name']??''));
 $adminEmail=strtolower(trim((string)($_POST['school_admin_email']??'')));
 $state=trim((string)($_POST['school_state']??''));
 $type=trim((string)($_POST['school_type']??''));
 $password=(string)($_POST['school_admin_password']??'');
 if (mb_strlen($schoolName)<3 || mb_strlen($schoolName)>180 || mb_strlen($adminName)<3 || mb_strlen($adminName)>180 || !filter_var($adminEmail,FILTER_VALIDATE_EMAIL) || strlen($password)<14 || strlen($password)>200 || mb_strlen($state)>80 || mb_strlen($type)>80) {
   $notice='Invalid school details. Use a valid email and a unique administrator password of at least 14 characters.';
 } else {
   try {
     $pdo->beginTransaction();
     if ((int)g('SELECT COUNT(*) FROM users WHERE email=?',[$adminEmail])>0) throw new RuntimeException('Administrator email is already registered.');
     q('INSERT INTO tenants(name,state,school_type) VALUES(?,?,?)',[$schoolName,$state,$type]);
     $newTenant=(int)$pdo->lastInsertId();
     q('INSERT INTO users(tenant_id,email,password_hash,role,name,active) VALUES(?,?,?,?,?,1)',[$newTenant,$adminEmail,password_hash($password,PASSWORD_DEFAULT),'school_admin',$adminName]);
     q('INSERT INTO audit_logs(tenant_id,user_id,action,entity_type,details,ip_address) VALUES(NULL,?,?,?,?,?)',[$u['id'],'tenant.created','tenant','New school ID: '.$newTenant,$_SERVER['REMOTE_ADDR']??'']);
     $pdo->commit();
     $notice='School created successfully. Its administrator can now log in.';
   } catch(Throwable $ex) {
     if ($pdo->inTransaction()) $pdo->rollBack();
     error_log('SchoolOS school provisioning failed: '.$ex->getMessage());
     $notice='School creation failed: '.$ex->getMessage();
   }
 }
