function sosSmartPanel($tenant){$templates=sosTemplates();$notice=$GLOBALS['sosNotice']??'';echo '<section class="card" style="margin-bottom:18px;padding:24px;border:1px solid var(--line)"><div style="display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap"><div><div class="ss-kicker">SCHOOLOS SMART SETUP</div><h2 style="margin:8px 0">Start with Nigerian school templates</h2><p class="muted">Choose an editable starter pack. Existing settings are never replaced. Review every suggestion before using it operationally.</p></div><span style="font-size:12px;border:1px solid var(--line);border-radius:20px;padding:8px;height:max-content">Optional · School-specific</span></div>';
if($notice!=='')echo '<div class="ss-note">'.e($notice).'</div>';
