// v2.8.1: guided starter creation, isolated to current school; existing records are never replaced.
if(me()&&me()['role']==='school_admin'&&($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['sos_quick'])){
 try{
  if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Security token expired.');
  if(!ssReady())throw new RuntimeException('Activate School Setup first.');
  $tenant=(int)me()['tenant_id'];$uid=(int)me()['id'];if($tenant<1)throw new RuntimeException('School account required.');
  $act=(string)$_POST['sos_quick'];$rows=[];
  if($act==='academic'){
   $year=(string)($_POST['academic_year']??'2026/2027');if(!preg_match('~^(20[2-9][0-9])/(20[2-9][0-9])$~D',$year,$m)||(int)$m[2]!==((int)$m[1]+1))throw new RuntimeException('Choose a valid academic session.');
   $term=(string)($_POST['current_term']??'First Term');if(!in_array($term,['First Term','Second Term','Third Term'],true))throw new RuntimeException('Choose a valid current term.');
   $rows[]=['sessions','guided_session_'.str_replace('/','_',$year),['name'=>$year,'start_date'=>'','end_date'=>'','status'=>'active']];
   foreach(['First Term','Second Term','Third Term'] as $i=>$name)$rows[]=['terms','guided_term_'.($i+1).'_'.str_replace('/','_',$year),['name'=>$name,'session_code'=>$year,'start_date'=>'','end_date'=>'','status'=>$name===$term?'active':'draft']];
  }elseif($act==='classes'){
   $groups=(array)($_POST['groups']??[]);$allowed=['nursery','primary','junior','senior'];$groups=array_values(array_intersect($allowed,array_map('strval',$groups)));if(!$groups)throw new RuntimeException('Select at least one class group.');
   $preset=['nursery'=>['Nursery 1','Nursery 2'],'primary'=>['Primary 1','Primary 2','Primary 3','Primary 4','Primary 5','Primary 6'],'junior'=>['JSS 1','JSS 2','JSS 3'],'senior'=>['SSS 1','SSS 2','SSS 3']];
   $arms=(string)($_POST['class_arms']??'none');if(!in_array($arms,['none','A','AB','ABC'],true))throw new RuntimeException('Invalid arm selection.');
   foreach($groups as $group){$rows[]=['levels','guided_level_'.$group,['name'=>ucfirst($group),'code'=>strtoupper($group),'sort_order'=>(string)(array_search($group,$allowed)+1)]];foreach($preset[$group] as $name){foreach($arms==='none'?['']:str_split($arms) as $arm){$key='guided_'.strtolower(str_replace(' ','_',$name)).($arm?'_'.strtolower($arm):'');$rows[]=['classes',$key,['name'=>$name,'arm'=>$arm,'level_code'=>strtoupper($group),'campus_code'=>'','capacity'=>'']];}}}
  }else throw new RuntimeException('Unknown setup action.');
  $pdo->beginTransaction();$added=0;foreach($rows as [$module,$key,$data]){if((int)g('SELECT COUNT(*) FROM school_setup_records WHERE tenant_id=? AND module_key=? AND record_key=?',[$tenant,$module,$key]))continue;ssSave($tenant,$module,$key,$data,$uid);$added++;}$pdo->commit();$GLOBALS['sosQuickNotice']=$added.' new records created; '.(count($rows)-$added).' existing starter records kept unchanged.';audit('school_setup.guided','school_setup',$act);
 }catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$GLOBALS['sosQuickNotice']='Error: '.$ex->getMessage();}
}
if(me()&&me()['role']==='school_admin'&&($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['sos_action'])){try{if(!hash_equals((string)($_SESSION['csrf']??''),(string)($_POST['csrf']??'')))throw new RuntimeException('Invalid security token.');if(!ssReady())throw new RuntimeException('Activate School Setup first.');$key=(string)($_POST['template']??'');$templates=sosTemplates();if(($_POST['sos_action']??'')!=='apply'||!isset($templates[$key]))throw new RuntimeException('Unknown template.');$tenant=(int)me()['tenant_id'];$uid=(int)me()['id'];if($tenant<1)throw new RuntimeException('School account required.');$pdo->beginTransaction();$added=0;foreach($templates[$key]['records'] as [$module,$record,$data]){if(g('SELECT COUNT(*) FROM school_setup_records WHERE tenant_id=? AND module_key=? AND record_key=?',[$tenant,$module,$record]))continue;ssSave($tenant,$module,$record,$data,$uid);$added++;}$pdo->commit();$GLOBALS['sosNotice']=$added.' suggested records added. Review and customise them before use.';audit('school_setup.smart_template','school_setup',$key);}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$GLOBALS['sosNotice']='Error: '.$ex->getMessage();}}

// School identity is read from the saved tenant-scoped setup configuration on every request.
$schoolIdentity=['name'=>'','primary'=>'#0d8c82','secondary'=>'#0c1c35','motto'=>'','logo'=>'','sidebar'=>'','surface'=>'','highlight'=>''];
if($tid>0){
 try{
  $schoolIdentity['name']=(string)(g('SELECT name FROM tenants WHERE id=?',[$tid])?:'');
  if(ssReady()){
   $brandRows=q("SELECT payload FROM school_setup_records WHERE tenant_id=? AND module_key='branding' AND active=1 ORDER BY updated_at DESC,id DESC LIMIT 1",[$tid])->fetchAll();
