    foreach(['primary_color'=>'primary','secondary_color'=>'secondary','sidebar_color'=>'sidebar','surface_color'=>'surface','highlight_color'=>'highlight'] as $field=>$target){$c=(string)($brand[$field]??'');if(preg_match('/^#[0-9a-fA-F]{6}$/D',$c))$schoolIdentity[$target]=$c;}
