   }}
  }
 }catch(Throwable $identityError){error_log('School identity lookup: '.$identityError->getMessage());}
}
$schoolTitle=$schoolIdentity['name']!==''?$schoolIdentity['name']:'Your School';
$schoolPrimary=$ecoRole==='platform_super_admin'?'#0d8c82':$schoolIdentity['primary'];
$schoolNavy=$ecoRole==='platform_super_admin'?'#0c1c35':$schoolIdentity['secondary'];
// Student Information System v3.1: explicit schema activation; never alters existing students.
function sisReady():bool {try{return (bool)q("SHOW TABLES LIKE 'sis_student_details'")->fetchColumn();}catch(Throwable $e){return false;}}
function sisInstall():void {global $pdo;
 $sql=[
 "CREATE TABLE IF NOT EXISTS sis_student_details(tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,dob DATE NULL,admission_date DATE NULL,previous_school VARCHAR(190) NULL,address TEXT NULL,emergency_name VARCHAR(180) NULL,emergency_phone VARCHAR(40) NULL,status VARCHAR(24) NOT NULL DEFAULT 'active',photo LONGBLOB NULL,photo_mime VARCHAR(30) NULL,verify_token CHAR(48) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,student_id),UNIQUE KEY uq_sis_token(verify_token),INDEX ix_sis_status(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS sis_guardians(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,phone VARCHAR(40) NULL,email VARCHAR(190) NULL,UNIQUE KEY uq_sis_guardian(tenant_id,name,phone),INDEX ix_sis_guardian(tenant_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
