function sisBarcode(string $value):string { // Code39: local SVG, no third-party tracking.
 $patterns=['0'=>'nnnwwnwnn','1'=>'wnnwnnnnw','2'=>'nnwwnnnnw','3'=>'wnwwnnnnn','4'=>'nnnwwnnnw','5'=>'wnnwwnnnn','6'=>'nnwwwnnnn','7'=>'nnnwnnwnw','8'=>'wnnwnnwnn','9'=>'nnwwnnwnn','A'=>'wnnnnwnnw','B'=>'nnwnnwnnw','C'=>'wnwnnwnnn','D'=>'nnnnwwnnw','E'=>'wnnnwwnnn','F'=>'nnwnwwnnn','G'=>'nnnnnwwnw','H'=>'wnnnnwwnn','I'=>'nnwnnwwnn','J'=>'nnnnwwwnn','K'=>'wnnnnnnww','L'=>'nnwnnnnww','M'=>'wnwnnnnwn','N'=>'nnnnwnnww','O'=>'wnnnwnnwn','P'=>'nnwnwnnwn','Q'=>'nnnnnnwww','R'=>'wnnnnnwwn','S'=>'nnwnnnwwn','T'=>'nnnnwnwwn','U'=>'wwnnnnnnw','V'=>'nwwnnnnnw','W'=>'wwwnnnnnn','X'=>'nwnnwnnnw','Y'=>'wwnnwnnnn','Z'=>'nwwnwnnnn','-'=>'nwnnnnwnw','.'=>'wwnnnnwnn',' '=>'nwwnnnwnn','*'=>'nwnnwnwnn','/'=>'nwnnwnwnn'];
 $value=strtoupper(preg_replace('/[^A-Za-z0-9. \/-]/','',mb_substr($value,0,45)));$x=6;$rect='';foreach(str_split('*'.$value.'*') as $ch){$pattern=$patterns[$ch]??$patterns['-'];foreach(str_split($pattern) as $i=>$width){$w=$width==='w'?5:2;if($i%2===0)$rect.='<rect x="'.$x.'" y="4" width="'.$w.'" height="48" fill="#0b233c"/>';$x+=$w;}$x+=2;}return '<svg role="img" aria-label="Admission ID barcode" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '.$x.' 56" style="max-width:340px;width:100%;height:70px">'.$rect.'</svg>';
}
