 "CREATE TABLE IF NOT EXISTS cb_exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,class_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,title VARCHAR(180) NOT NULL,mode VARCHAR(20) NOT NULL DEFAULT 'school',duration_minutes INT NOT NULL DEFAULT 45,attempt_limit INT NOT NULL DEFAULT 1,question_limit INT NOT NULL DEFAULT 0,pass_percent DECIMAL(5,2) NOT NULL DEFAULT 50,access_code VARCHAR(60) NOT NULL DEFAULT '',randomize TINYINT NOT NULL DEFAULT 1,published TINYINT NOT NULL DEFAULT 0,results_published TINYINT NOT NULL DEFAULT 0,starts_at DATETIME NULL,ends_at DATETIME NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,class_id),INDEX(tenant_id,subject_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS cb_questions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,exam_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(16) NOT NULL,body TEXT NOT NULL,media_url VARCHAR(500) NOT NULL DEFAULT '',options_json TEXT NULL,correct_answer TEXT NULL,points DECIMAL(8,2) NOT NULL DEFAULT 1,explanation TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,exam_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS cb_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,exam_id BIGINT UNSIGNED NOT NULL,student_id BIGINT NOT NULL,user_id BIGINT NOT NULL,started_at DATETIME NOT NULL,expires_at DATETIME NOT NULL,submitted_at DATETIME NULL,status VARCHAR(20) NOT NULL DEFAULT 'in_progress',question_order_json MEDIUMTEXT NOT NULL,score DECIMAL(9,2) NULL,max_score DECIMAL(9,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,exam_id,student_id),INDEX(tenant_id,user_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS cb_answers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,attempt_id BIGINT UNSIGNED NOT NULL,question_id BIGINT UNSIGNED NOT NULL,response MEDIUMTEXT NULL,awarded DECIMAL(9,2) NULL,graded_by BIGINT NULL,graded_at DATETIME NULL,feedback TEXT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_answer(attempt_id,question_id),INDEX(tenant_id,attempt_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS cb_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,attempt_id BIGINT UNSIGNED NOT NULL,event_type VARCHAR(40) NOT NULL,details VARCHAR(400) NOT NULL DEFAULT '',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,attempt_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS cb_reviews(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,answer_id BIGINT UNSIGNED NOT NULL,reviewer_id BIGINT NOT NULL,previous_score DECIMAL(9,2) NULL,new_score DECIMAL(9,2) NOT NULL,reason VARCHAR(500) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,answer_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
 ];foreach($sql as $s)q($s);
}
function cbExam(int $tid,int $id):array {$r=q('SELECT * FROM cb_exams WHERE tenant_id=? AND id=?',[$tid,$id])->fetch();if(!$r)throw new RuntimeException('Exam not found.');return $r;}
function cbAttempt(int $tid,int $id):array {$r=q('SELECT * FROM cb_attempts WHERE tenant_id=? AND id=?',[$tid,$id])->fetch();if(!$r)throw new RuntimeException('Attempt not found.');return $r;}
function cbStudentId(int $tid,int $uid):int {
 try{$ids=q("SELECT DISTINCT s.id FROM ecosystem_links l JOIN students s ON s.id=l.student_id AND s.tenant_id=l.tenant_id JOIN users u ON u.id=l.user_id AND u.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.user_id=? AND l.relation_type='student' AND u.role='student' AND u.active=1 LIMIT 2",[$tid,$uid])->fetchAll(PDO::FETCH_COLUMN);return count($ids)===1?(int)$ids[0]:0;}catch(Throwable $e){return 0;}
}
function cbRecalc(int $tid,int $attempt):void {$s=q('SELECT COALESCE(SUM(a.awarded),0) total,COUNT(*) cnt FROM cb_answers a WHERE a.tenant_id=? AND a.attempt_id=?',[$tid,$attempt])->fetch();$pending=(int)g("SELECT COUNT(*) FROM cb_answers a JOIN cb_questions q ON q.id=a.question_id AND q.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.attempt_id=? AND q.kind IN ('essay','short') AND a.awarded IS NULL",[$tid,$attempt]);q('UPDATE cb_attempts SET score=?,status=CASE WHEN submitted_at IS NULL THEN status WHEN ?=0 THEN \'graded\' ELSE \'grading\' END WHERE tenant_id=? AND id=?',[(float)$s['total'],$pending,$tid,$attempt]);}
function cbEvent(int $tid,int $attempt,string $event,string $details=''):void {q('INSERT INTO cb_events(tenant_id,attempt_id,event_type,details) VALUES(?,?,?,?)',[$tid,$attempt,$event,mb_substr($details,0,400)]);}
