 foreach($questions as $question){$answer=q('SELECT * FROM cb_answers WHERE tenant_id=? AND attempt_id=? AND question_id=?',[$tid,$attempt,$question['id']])->fetch();$kind=$question['kind'];if(in_array($kind,['mcq','truefalse'],true)){$earned=(trim((string)$answer['response'])===trim((string)$question['correct_answer']))?(float)$question['points']:0;q('UPDATE cb_answers SET awarded=?,graded_at=NOW() WHERE id=? AND tenant_id=?',[$earned,$answer['id'],$tid]);}}
