 if($act==='exam'){if(!$cbAdmin)throw new RuntimeException('Administrator only.');$class=(int)($_POST['class_id']??0);$subject=(int)($_POST['subject_id']??0);if(!g('SELECT id FROM classes WHERE tenant_id=? AND id=?',[$tid,$class])||!g('SELECT id FROM subjects WHERE tenant_id=? AND id=?',[$tid,$subject]))throw new RuntimeException('Choose a valid class and subject.');$title=trim((string)($_POST['title']??''));$mode=(string)($_POST['mode']??'school');if(mb_strlen($title)<4||!in_array($mode,['school','waec','neco','jamb'],true))throw new RuntimeException('Provide an exam title and mode.');q('INSERT INTO cb_exams(tenant_id,class_id,subject_id,title,mode,duration_minutes,attempt_limit,question_limit,pass_percent,access_code,randomize,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',[$tid,$class,$subject,$title,$mode,max(1,min(300,(int)($_POST['minutes']??45))),max(1,min(20,(int)($_POST['limit']??1))),max(0,(int)($_POST['question_limit']??0)),max(0,min(100,(float)($_POST['pass']??50))),trim((string)($_POST['code']??'')),isset($_POST['randomize'])?1:0,(int)$u['id']]);$newExamId=(int)$pdo->lastInsertId();header('Location: ?s=exams&tab=questions&exam='.$newExamId.'&created=1',true,303);exit;}
