 elseif(in_array($act,['save','submit','integrity'],true)){if(!$cbLearner)throw new RuntimeException('Student only.');$a=cbAttempt($tid,$attemptId);if((int)$a['user_id']!==(int)$u['id'])throw new RuntimeException('Attempt access denied.');if($a['submitted_at'])throw new RuntimeException('Attempt already submitted.');if($act==='integrity'){cbEvent($tid,$attemptId,'integrity',trim((string)($_POST['event']??'browser event')));header('Content-Type:application/json');echo json_encode(['ok'=>true]);exit;}if($a['expires_at']<=date('Y-m-d H:i:s')){cbFinalize($tid,$attemptId);throw new RuntimeException('Time expired. Your saved answers were submitted.');}$answers=(array)($_POST['answers']??[]);foreach($answers as $qid=>$response){$qid=(int)$qid;if(!is_scalar($response))continue;$text=mb_substr(trim((string)$response),0,12000);q('UPDATE cb_answers SET response=? WHERE tenant_id=? AND attempt_id=? AND question_id=?',[$text,$tid,$attemptId,$qid]);}if($act==='submit'){cbFinalize($tid,$attemptId);$cbNotice='Attempt submitted successfully.';}else{$cbNotice='Answers saved. You can resume this exam.';}}
