// SchoolOS LMS v3.9: tenant-scoped courses, lessons, submissions, discussions and progress.
function lmReady():bool {try{return (bool)q("SHOW TABLES LIKE 'lm_courses'")->fetchColumn();}catch(Throwable $e){return false;}}
function lmInstall():void {global $pdo;foreach([
"CREATE TABLE IF NOT EXISTS lm_courses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,class_id BIGINT NOT NULL,subject_id BIGINT NOT NULL,teacher_id BIGINT NULL,title VARCHAR(180) NOT NULL,description TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,class_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_lessons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,course_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,content MEDIUMTEXT NULL,resource_url VARCHAR(1000) NULL,lesson_type VARCHAR(24) NOT NULL DEFAULT 'lesson',position INT NOT NULL DEFAULT 1,available_at DATETIME NULL,due_at DATETIME NULL,points DECIMAL(8,2) NOT NULL DEFAULT 100,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,course_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,lesson_id BIGINT UNSIGNED NOT NULL,student_id BIGINT NOT NULL,answer MEDIUMTEXT NULL,filename VARCHAR(190) NULL,filemime VARCHAR(100) NULL,filedata MEDIUMBLOB NULL,score DECIMAL(8,2) NULL,feedback TEXT NULL,graded_by BIGINT NULL,submitted_at DATETIME NOT NULL,graded_at DATETIME NULL,UNIQUE KEY uq_lm_submit(tenant_id,lesson_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_progress(tenant_id BIGINT NOT NULL,lesson_id BIGINT UNSIGNED NOT NULL,student_id BIGINT NOT NULL,completed_at DATETIME NOT NULL,PRIMARY KEY(tenant_id,lesson_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_discussions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,course_id BIGINT UNSIGNED NOT NULL,user_id BIGINT NOT NULL,message TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,course_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_live(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,course_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,provider VARCHAR(24) NOT NULL,meeting_url VARCHAR(1000) NOT NULL,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,course_id,starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_groups(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,course_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,brief TEXT NULL,deadline DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,course_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_group_members(tenant_id BIGINT NOT NULL,group_id BIGINT UNSIGNED NOT NULL,student_id BIGINT NOT NULL,PRIMARY KEY(tenant_id,group_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS lm_badges(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,course_id BIGINT UNSIGNED NOT NULL,student_id BIGINT NOT NULL,label VARCHAR(120) NOT NULL,awarded_by BIGINT NOT NULL,awarded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_lm_badge(tenant_id,course_id,student_id,label)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql){$pdo->exec($sql);}}
function lmStudent(int $tid,int $uid):int {return cbStudentId($tid,$uid);}
function lmCourse(int $tid,int $id):array {return q('SELECT * FROM lm_courses WHERE tenant_id=? AND id=?',[$tid,$id])->fetch()?:[];}
function lmAllowed(int $tid,array $course,int $student):bool {return $student>0 && (int)g('SELECT class_id FROM students WHERE tenant_id=? AND id=?',[$tid,$student])===(int)$course['class_id'];}
function lmStaff(array $u,array $course=[]):bool {
 if(in_array($u['role']??'',['school_admin','admin'],true))return true;
 if(($u['role']??'')!=='teacher')return false;
 if(!$course)return true;
 if((int)($course['teacher_id']??0)!==(int)$u['id'])return false;
 if(function_exists('lp_scope')&&isset($course['class_id'],$course['subject_id'])){try{lp_scope($u,(int)$course['class_id'],(int)$course['subject_id']);}catch(Throwable $e){return false;}}
 return true;
}
if(me()&&isset($_GET['lm_file'])&&lmReady()){
 $tid=(int)me()['tenant_id'];$id=(int)$_GET['lm_file'];$f=q('SELECT s.*,l.course_id,c.class_id,c.teacher_id,c.status course_status FROM lm_submissions s JOIN lm_lessons l ON l.id=s.lesson_id AND l.tenant_id=s.tenant_id JOIN lm_courses c ON c.id=l.course_id AND c.tenant_id=l.tenant_id WHERE s.tenant_id=? AND s.id=?',[$tid,$id])->fetch();
 if(!$f||!$f['filedata']){http_response_code(404);exit('Attachment not found.');}
 $sid=cbStudentId($tid,(int)me()['id']);$owner=$sid&&(int)$f['student_id']===$sid;$staff=lmStaff(me(),$f);
 if(!$owner&&!$staff){http_response_code(403);exit('Access denied.');}
 header('Content-Type: '.$f['filemime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename=\"'.preg_replace('/[^a-zA-Z0-9._-]/','_', $f['filename']).'\"');header('Cache-Control: private, no-store');echo $f['filedata'];exit;
}
$lmNotice='';
if(me()&&($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['lm_action'])){
 $u=me();global $pdo;$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$sid=lmReady()?lmStudent($tid,$uid):0;
 if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))){$lmNotice='Session expired. Refresh and try again.';}
 else try{
  $act=(string)$_POST['lm_action'];$cid=(int)($_POST['course_id']??0);$course=lmReady()?lmCourse($tid,$cid):[];
  if($act==='install'){if(!in_array($u['role'],['school_admin','admin'],true))throw new Exception('Administrator permission required.');lmInstall();$lmNotice='Learning Management System activated.';}
  else{
   if(!lmReady())throw new Exception('Activate the LMS first.');
   if($act==='course'){
    if(!in_array($u['role'],['school_admin','admin'],true))throw new Exception('Administrator permission required.');
    $class=(int)($_POST['class_id']??0);$subject=(int)($_POST['subject_id']??0);$teacher=(int)($_POST['teacher_id']??0);
    if(!g('SELECT id FROM classes WHERE tenant_id=? AND id=?',[$tid,$class])||!g('SELECT id FROM subjects WHERE tenant_id=? AND id=?',[$tid,$subject]))throw new Exception('Select a valid class and subject.');
    if($teacher&&!g("SELECT id FROM users WHERE tenant_id=? AND id=? AND role='teacher'",[$tid,$teacher]))throw new Exception('Select a valid teacher.');
    $title=trim((string)($_POST['title']??''));if(strlen($title)<3)throw new Exception('Course title is required.');
    q('INSERT INTO lm_courses(tenant_id,class_id,subject_id,teacher_id,title,description) VALUES(?,?,?,?,?,?)',[$tid,$class,$subject,$teacher?:null,$title,trim((string)($_POST['description']??''))]);$cid=(int)$pdo->lastInsertId();$lmNotice='Course created. Add your first lesson below.';$_GET['course']=$cid;$_GET['view']='lessons';
   }else{
    if(!$course)throw new Exception('Course not found.');
    $staff=lmStaff($u,$course);$enrolled=lmAllowed($tid,$course,$sid);
    if($act==='publish'){if(!$staff)throw new Exception('Access denied.');$on=isset($_POST['publish'])?'published':'draft';q('UPDATE lm_courses SET status=? WHERE tenant_id=? AND id=?',[$on,$tid,$cid]);$lmNotice='Course visibility updated.';}
    elseif($act==='lesson'){
     if(!$staff)throw new Exception('Access denied.');$title=trim((string)($_POST['title']??''));$kind=(string)($_POST['kind']??'lesson');if(!in_array($kind,['lesson','homework','revision','quiz','resource'],true)||strlen($title)<3)throw new Exception('Provide a valid lesson title and type.');
     $url=trim((string)($_POST['url']??''));if($url&&(!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https'))throw new Exception('Resource link must use HTTPS.');
     q('INSERT INTO lm_lessons(tenant_id,course_id,title,content,resource_url,lesson_type,position,due_at,points) VALUES(?,?,?,?,?,?,?,?,?)',[$tid,$cid,$title,trim((string)($_POST['content']??'')),$url,$kind,max(1,(int)($_POST['position']??1)),($_POST['due_at']??'')?:null,max(1,min(1000,(float)($_POST['points']??100)))]);$lmNotice='Learning activity saved.';
    }elseif($act==='complete'){
     if(!$enrolled||$course['status']!=='published')throw new Exception('Student access required.');$lid=(int)($_POST['lesson_id']??0);$lesson=q('SELECT id FROM lm_lessons WHERE tenant_id=? AND course_id=? AND id=?',[$tid,$cid,$lid])->fetch();if(!$lesson)throw new Exception('Lesson not found.');
     q('INSERT IGNORE INTO lm_progress(tenant_id,lesson_id,student_id,completed_at) VALUES(?,?,?,NOW())',[$tid,$lid,$sid]);$lmNotice='Progress saved.';
    }elseif($act==='submit'){
     if(!$enrolled||$course['status']!=='published')throw new Exception('Student access required.');$lid=(int)($_POST['lesson_id']??0);$lesson=q("SELECT * FROM lm_lessons WHERE tenant_id=? AND course_id=? AND id=? AND lesson_type IN ('homework','quiz')",[$tid,$cid,$lid])->fetch();if(!$lesson)throw new Exception('Assignment not found.');
     if($lesson['due_at']&&strtotime($lesson['due_at'])<time())throw new Exception('Submission deadline has passed.');
     $answer=trim((string)($_POST['answer']??''));$filename=null;$mime=null;$blob=null;
     if(!empty($_FILES['attachment']['name'])){$f=$_FILES['attachment'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>3000000)throw new Exception('Attachment must be under 3 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['application/pdf','image/jpeg','image/png','text/plain'],true))throw new Exception('Only PDF, JPG, PNG or text files are accepted.');$filename=substr(basename($f['name']),0,180);$blob=file_get_contents($f['tmp_name']);}
     if(!$answer&&!$blob)throw new Exception('Enter your answer or attach a file.');
     q('INSERT INTO lm_submissions(tenant_id,lesson_id,student_id,answer,filename,filemime,filedata,submitted_at) VALUES(?,?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE answer=VALUES(answer),filename=VALUES(filename),filemime=VALUES(filemime),filedata=VALUES(filedata),submitted_at=NOW(),score=NULL,feedback=NULL,graded_by=NULL,graded_at=NULL',[$tid,$lid,$sid,$answer,$filename,$mime,$blob]);$lmNotice='Assignment submitted successfully.';
    }elseif($act==='grade'){
     if(!$staff)throw new Exception('Teacher or administrator permission required.');$sub=(int)($_POST['submission_id']??0);$record=q('SELECT s.id,l.points FROM lm_submissions s JOIN lm_lessons l ON l.id=s.lesson_id AND l.tenant_id=s.tenant_id WHERE s.tenant_id=? AND l.course_id=? AND s.id=?',[$tid,$cid,$sub])->fetch();if(!$record)throw new Exception('Submission not found.');$score=(float)($_POST['score']??-1);if($score<0||$score>(float)$record['points'])throw new Exception('Score exceeds available marks.');q('UPDATE lm_submissions SET score=?,feedback=?,graded_by=?,graded_at=NOW() WHERE tenant_id=? AND id=?',[$score,trim((string)($_POST['feedback']??'')),$uid,$tid,$sub]);$lmNotice='Grade and feedback saved.';
    }elseif($act==='discuss'){
     if(!$staff&&!$enrolled)throw new Exception('Course access required.');$msg=trim((string)($_POST['message']??''));if(strlen($msg)<3||strlen($msg)>3000)throw new Exception('Message must be 3–3000 characters.');q('INSERT INTO lm_discussions(tenant_id,course_id,user_id,message,status) VALUES(?,?,?,?,?)',[$tid,$cid,$uid,$msg,$staff?'approved':'pending']);$lmNotice=$staff?'Discussion posted.':'Message submitted for moderation.';
    }elseif($act==='moderate'){
     if(!$staff)throw new Exception('Access denied.');$id=(int)($_POST['message_id']??0);$status=($_POST['decision']??'')==='approve'?'approved':'rejected';q('UPDATE lm_discussions SET status=? WHERE tenant_id=? AND course_id=? AND id=?',[$status,$tid,$cid,$id]);$lmNotice='Discussion reviewed.';
    }elseif($act==='live'){
     if(!$staff)throw new Exception('Access denied.');$provider=(string)($_POST['provider']??'');$url=trim((string)($_POST['meeting_url']??''));if(!in_array($provider,['zoom','meet','external'],true)||!filter_var($url,FILTER_VALIDATE_URL)||parse_url($url,PHP_URL_SCHEME)!=='https')throw new Exception('Provide a secure meeting link.');$start=str_replace('T',' ',(string)($_POST['starts_at']??''));$end=str_replace('T',' ',(string)($_POST['ends_at']??''));if(strtotime($end)<=strtotime($start))throw new Exception('Class end must follow start.');q('INSERT INTO lm_live(tenant_id,course_id,title,provider,meeting_url,starts_at,ends_at) VALUES(?,?,?,?,?,?,?)',[$tid,$cid,trim((string)($_POST['title']??'Live class')),$provider,$url,$start,$end]);$lmNotice='Live-class session scheduled.';
    }elseif($act==='group'){
     if(!$staff)throw new Exception('Access denied.');$name=trim((string)($_POST['name']??''));if(strlen($name)<2)throw new Exception('Group name required.');q('INSERT INTO lm_groups(tenant_id,course_id,name,brief,deadline) VALUES(?,?,?,?,?)',[$tid,$cid,$name,trim((string)($_POST['brief']??'')),($_POST['deadline']??'')?:null]);$lmNotice='Group created.';
    }elseif($act==='member'){
     if(!$staff)throw new Exception('Access denied.');$group=(int)($_POST['group_id']??0);$student=(int)($_POST['student_id']??0);if(!g('SELECT id FROM lm_groups WHERE tenant_id=? AND course_id=? AND id=?',[$tid,$cid,$group])||!lmAllowed($tid,$course,$student))throw new Exception('Select a student in this class and a valid group.');q('INSERT IGNORE INTO lm_group_members(tenant_id,group_id,student_id) VALUES(?,?,?)',[$tid,$group,$student]);$lmNotice='Student added to group.';
    }elseif($act==='badge'){
     if(!$staff)throw new Exception('Access denied.');$student=(int)($_POST['student_id']??0);$label=trim((string)($_POST['label']??''));if(!lmAllowed($tid,$course,$student)||strlen($label)<3)throw new Exception('Select a valid student and badge name.');q('INSERT IGNORE INTO lm_badges(tenant_id,course_id,student_id,label,awarded_by) VALUES(?,?,?,?,?)',[$tid,$cid,$student,$label,$uid]);$lmNotice='Badge awarded.';
    }else throw new Exception('Unsupported LMS action.');
   }
  }
  audit('lms.'.$act,'courses',(string)$cid);
 }catch(Throwable $ex){$lmNotice='Error: '.$ex->getMessage();}
}


// SchoolOS v4.1.0 — attendance, behaviour, welfare and communications.
function awReady():bool {try{return (bool)q("SHOW TABLES LIKE 'aw_period_attendance'")->fetchColumn();}catch(Throwable $e){return false;}}
function awInstall():void {global $pdo;foreach([
"CREATE TABLE IF NOT EXISTS aw_period_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,class_id BIGINT NOT NULL,attendance_date DATE NOT NULL,period_name VARCHAR(80) NOT NULL,status VARCHAR(20) NOT NULL,reason VARCHAR(300) NULL,recorded_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_aw_period(tenant_id,student_id,attendance_date,period_name),INDEX(tenant_id,class_id,attendance_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_staff_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,user_id BIGINT NOT NULL,work_date DATE NOT NULL,clock_in DATETIME NULL,clock_out DATETIME NULL,status VARCHAR(24) NOT NULL DEFAULT 'present',recorded_by BIGINT NOT NULL,UNIQUE KEY uq_aw_staff(tenant_id,user_id,work_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_leave(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,person_type VARCHAR(12) NOT NULL,person_id BIGINT NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,reason TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',reviewed_by BIGINT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status,starts_on)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_cases(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,kind VARCHAR(25) NOT NULL,severity VARCHAR(12) NOT NULL DEFAULT 'low',title VARCHAR(200) NOT NULL,details TEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'open',confidential TINYINT NOT NULL DEFAULT 0,assigned_to BIGINT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,INDEX(tenant_id,student_id,kind),INDEX(tenant_id,status,severity)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_case_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,case_id BIGINT NOT NULL,note TEXT NOT NULL,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,case_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_sickbay(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,arrived_at DATETIME NOT NULL,departed_at DATETIME NULL,complaint TEXT NOT NULL,care_given TEXT NULL,outcome VARCHAR(40) NOT NULL DEFAULT 'observing',recorded_by BIGINT NOT NULL,INDEX(tenant_id,student_id,arrived_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_medications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,medication VARCHAR(180) NOT NULL,dose VARCHAR(120) NOT NULL,administered_at DATETIME NOT NULL,authorisation_ref VARCHAR(200) NOT NULL,notes TEXT NULL,administered_by BIGINT NOT NULL,INDEX(tenant_id,student_id,administered_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,alert_type VARCHAR(35) NOT NULL,message TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',recipient VARCHAR(190) NULL,sent_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_escalations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,case_id BIGINT NOT NULL,contact_name VARCHAR(180) NOT NULL,contact_phone VARCHAR(40) NOT NULL,action_taken TEXT NOT NULL,escalated_by BIGINT NOT NULL,escalated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,case_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS aw_scan_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,student_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_aw_token(token_hash),INDEX(tenant_id,student_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql)$pdo->exec($sql);}
function awOwnStudent(int $tid,int $id):bool{return $id>0&&(bool)g('SELECT id FROM students WHERE tenant_id=? AND id=?',[$tid,$id]);}
function awField(string $key,int $max=500):string{return mb_substr(trim((string)($_POST[$key]??'')),0,$max);}
$awNotice='';$awTab=(string)($_GET['tab']??'overview');$awTabs=['overview','register','staff','cases','sickbay','alerts','reports','settings'];if(!in_array($awTab,$awTabs,true))$awTab='overview';
if(isset($_POST['aw_action'])&&me()){
 try{
  if(!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??'')))throw new RuntimeException('Session expired. Refresh and retry.');
  $act=awField('aw_action',35);$admin=$ecoRole==='school_admin';$staff=in_array($ecoRole,['school_admin','teacher','staff'],true);$welfare=$admin; // Confidential safeguarding/medication: admin only until explicit welfare RBAC is provisioned.
