  else {if(!awReady())throw new RuntimeException('Ask the school administrator to activate the workspace first.');
   $student=(int)($_POST['student_id']??0);$date=awField('attendance_date',10)?:date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4)))throw new RuntimeException('Choose a valid date.');
   if($act==='register'){$class=(int)($_POST['class_id']??0);if(!g('SELECT id FROM classes WHERE tenant_id=? AND id=?',[$tid,$class]))throw new RuntimeException('Select a valid class.');$period=awField('period',70)?:'Daily';$marks=(array)($_POST['marks']??[]);if(!$marks)throw new RuntimeException('Select attendance statuses first.');$pdo->beginTransaction();try{foreach($marks as $sid=>$status){$sid=(int)$sid;if(!in_array($status,['present','absent','late','excused'],true)||!g('SELECT id FROM students WHERE tenant_id=? AND class_id=? AND id=?',[$tid,$class,$sid]))throw new RuntimeException('Invalid student or status.');q('INSERT INTO aw_period_attendance(tenant_id,student_id,class_id,attendance_date,period_name,status,recorded_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by)',[$tid,$sid,$class,$date,$period,$status,me()['id']]);if($period==='Daily'){if(g('SELECT id FROM attendance WHERE tenant_id=? AND student_id=? AND attendance_date=?',[$tid,$sid,$date]))q('UPDATE attendance SET status=?,reason=? WHERE tenant_id=? AND student_id=? AND attendance_date=?',[$status,'Recorded through SchoolOS Welfare',$tid,$sid,$date]);else q('INSERT INTO attendance(tenant_id,student_id,attendance_date,status,reason) VALUES(?,?,?,?,?)',[$tid,$sid,$date,$status,'Recorded through SchoolOS Welfare']);}if(in_array($status,['absent','late'],true)&&!g('SELECT id FROM aw_alerts WHERE tenant_id=? AND student_id=? AND alert_type=? AND message=?',[$tid,$sid,'attendance','Student marked '.$status.' on '.$date.' ('.$period.').'])){q('INSERT INTO aw_alerts(tenant_id,student_id,alert_type,message) VALUES(?,?,?,?)',[$tid,$sid,'attendance','Student marked '.$status.' on '.$date.' ('.$period.').']);}}$pdo->commit();}catch(Throwable $ex){$pdo->rollBack();throw $ex;}$awNotice='Attendance saved for '.count($marks).' learners. Parent alerts queued for review.';}
   elseif($act==='staff_clock'){$uid=(int)($_POST['user_id']??0);if(!$admin&&$uid!==(int)me()['id'])throw new RuntimeException('You may only record your own attendance.');if(!g('SELECT id FROM users WHERE tenant_id=? AND id=?',[$tid,$uid]))throw new RuntimeException('Invalid staff account.');$mode=awField('mode',10);if($mode==='in')q('INSERT INTO aw_staff_attendance(tenant_id,user_id,work_date,clock_in,recorded_by) VALUES(?,?,?,NOW(),?) ON DUPLICATE KEY UPDATE clock_in=COALESCE(clock_in,NOW())',[$tid,$uid,$date,me()['id']]);elseif($mode==='out')q('UPDATE aw_staff_attendance SET clock_out=NOW() WHERE tenant_id=? AND user_id=? AND work_date=? AND clock_in IS NOT NULL AND clock_out IS NULL',[$tid,$uid,$date]);else throw new RuntimeException('Invalid clock action.');$awNotice='Staff clock record updated.';}
   elseif($act==='leave'){$type=awField('person_type',12);$person=$type==='staff'?(int)me()['id']:$student;if($type==='student'&&!awOwnStudent($tid,$person))throw new RuntimeException('Select a student.');if(!in_array($type,['student','staff'],true))throw new RuntimeException('Invalid leave type.');$from=awField('starts_on',10);$to=awField('ends_on',10);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$to<$from)throw new RuntimeException('Check leave dates.');$reason=awField('reason',1500);if(mb_strlen($reason)<8)throw new RuntimeException('Explain the leave request.');q('INSERT INTO aw_leave(tenant_id,person_type,person_id,starts_on,ends_on,reason) VALUES(?,?,?,?,?,?)',[$tid,$type,$person,$from,$to,$reason]);$awNotice='Leave request submitted for approval.';}
   elseif($act==='leave_review'){$admin||throw new RuntimeException('Administrator required.');$decision=awField('decision',12);if(!in_array($decision,['approved','rejected'],true))throw new RuntimeException('Invalid decision.');q("UPDATE aw_leave SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE tenant_id=? AND id=? AND status='pending'",[$decision,me()['id'],$tid,(int)($_POST['leave_id']??0)]);$awNotice='Leave decision recorded.';}
   elseif($act==='case'){$kind=awField('kind',25);if(!in_array($kind,['incident','counselling','safeguarding','merit'],true))throw new RuntimeException('Invalid record type.');if(in_array($kind,['counselling','safeguarding'],true)&&!$welfare)throw new RuntimeException('Confidential case access restricted.');if(!awOwnStudent($tid,$student))throw new RuntimeException('Select a student.');$title=awField('title',180);$details=awField('details',4000);if(mb_strlen($title)<4||mb_strlen($details)<10)throw new RuntimeException('Add a title and meaningful description.');$severity=awField('severity',12);if(!in_array($severity,['low','medium','high','critical'],true))throw new RuntimeException('Invalid severity.');q('INSERT INTO aw_cases(tenant_id,student_id,kind,severity,title,details,confidential,created_by) VALUES(?,?,?,?,?,?,?,?)',[$tid,$student,$kind,$severity,$title,$details,in_array($kind,['counselling','safeguarding'],true)?1:0,me()['id']]);$awNotice='Record saved to student welfare history.';}
   elseif($act==='case_note'){$id=(int)($_POST['case_id']??0);$case=q('SELECT * FROM aw_cases WHERE tenant_id=? AND id=?',[$tid,$id])->fetch();if(!$case||($case['confidential']&&!$welfare))throw new RuntimeException('Case not available.');$note=awField('note',3000);if(mb_strlen($note)<5)throw new RuntimeException('Enter a meaningful update.');q('INSERT INTO aw_case_notes(tenant_id,case_id,note,created_by) VALUES(?,?,?,?)',[$tid,$id,$note,me()['id']]);if(awField('close',1)==='1')q("UPDATE aw_cases SET status='closed',closed_at=NOW() WHERE tenant_id=? AND id=?",[$tid,$id]);$awNotice='Case update saved.';}
   elseif($act==='sickbay'){$welfare||throw new RuntimeException('Restricted to school administrators.');if(!awOwnStudent($tid,$student))throw new RuntimeException('Select a student.');$complaint=awField('complaint',1500);if(mb_strlen($complaint)<5)throw new RuntimeException('Describe the concern.');q('INSERT INTO aw_sickbay(tenant_id,student_id,arrived_at,complaint,care_given,recorded_by) VALUES(?,?,NOW(),?,?,?)',[$tid,$student,$complaint,awField('care_given',1500),me()['id']]);$awNotice='Sick bay visit recorded.';}
   elseif($act==='medication'){$welfare||throw new RuntimeException('Medication records restricted.');if(!awOwnStudent($tid,$student))throw new RuntimeException('Select a student.');$ref=awField('authorisation_ref',180);if(mb_strlen($ref)<5)throw new RuntimeException('Record a valid written authorisation reference.');q('INSERT INTO aw_medications(tenant_id,student_id,medication,dose,administered_at,authorisation_ref,notes,administered_by) VALUES(?,?,?,?,NOW(),?,?,?)',[$tid,$student,awField('medication',150),awField('dose',100),$ref,awField('notes',1000),me()['id']]);$awNotice='Restricted medication administration logged.';}
   elseif($act==='escalate'){$welfare||throw new RuntimeException('Administrator required.');$id=(int)($_POST['case_id']??0);if(!g('SELECT id FROM aw_cases WHERE tenant_id=? AND id=?',[$tid,$id]))throw new RuntimeException('Invalid case.');$action=awField('action_taken',1500);if(mb_strlen($action)<10)throw new RuntimeException('Describe the escalation action.');q('INSERT INTO aw_escalations(tenant_id,case_id,contact_name,contact_phone,action_taken,escalated_by) VALUES(?,?,?,?,?,?)',[$tid,$id,awField('contact_name',150),awField('contact_phone',35),$action,me()['id']]);q("UPDATE aw_cases SET status='escalated' WHERE tenant_id=? AND id=?",[$tid,$id]);$awNotice='Emergency escalation recorded. Contact emergency services directly when immediate assistance is needed.';}
   elseif($act==='alert_review'){$admin||throw new RuntimeException('Administrator required.');q("UPDATE aw_alerts SET status='reviewed' WHERE tenant_id=? AND id=? AND status='pending'",[$tid,(int)($_POST['alert_id']??0)]);$awNotice='Alert reviewed. No message was sent automatically.';}
   else throw new RuntimeException('Unknown welfare action.');audit('welfare.'.$act,'attendance_welfare','');
  }
 }catch(Throwable $ex){$awNotice='Error: '.$ex->getMessage();}
}


// v4.1.0 Communications Hub and secure attendance scanning.
function cmReady():bool {try{return (bool)q("SHOW TABLES LIKE 'cm_posts'")->fetchColumn();}catch(Throwable $e){return false;}}
function cmInstall():void {global $pdo;foreach([
"CREATE TABLE IF NOT EXISTS cm_posts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,author_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,audience VARCHAR(30) NOT NULL DEFAULT 'all',class_id BIGINT NULL,recipient_id BIGINT NULL,kind VARCHAR(20) NOT NULL DEFAULT 'announcement',pinned TINYINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,created_at),INDEX(tenant_id,audience,class_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cm_comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,post_id BIGINT NOT NULL,author_id BIGINT NOT NULL,body TEXT NOT NULL,status VARCHAR(15) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,post_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cm_reads(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,post_id BIGINT NOT NULL,user_id BIGINT NOT NULL,read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_read(tenant_id,post_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cm_email_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,post_id BIGINT NULL,recipient VARCHAR(190) NOT NULL,status VARCHAR(15) NOT NULL,error_message VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cm_devices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,device_name VARCHAR(120) NOT NULL,token_hash CHAR(64) NOT NULL,active TINYINT NOT NULL DEFAULT 1,created_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_device_token(token_hash),INDEX(tenant_id,active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS cm_scan_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT NOT NULL,device_id BIGINT NOT NULL,student_id BIGINT NOT NULL,scan_method VARCHAR(15) NOT NULL,scanned_by BIGINT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,student_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
] as $sql)$pdo->exec($sql);}
function cmPhone(string $raw):string {$digits=preg_replace('/\D+/','',$raw);if(str_starts_with($digits,'0')&&strlen($digits)===11)$digits='234'.substr($digits,1);return strlen($digits)>=10&&strlen($digits)<=15?$digits:'';}
function cmAllowed(array $p,string $role,int $uid,int $tid):bool {
 if($role==='school_admin')return true;
 if($p['recipient_id']!==null)return (int)$p['recipient_id']===$uid;
 if($p['audience']==='all')return true;
 if($p['audience']==='teachers')return $role==='teacher';
 if($p['audience']==='staff')return in_array($role,['teacher','staff','admissions'],true);
 if($p['audience']==='parents')return $role==='parent';
 if($p['audience']==='students')return $role==='student';
 if($p['audience']==='class'){
   if($role==='parent')return (bool)g("SELECT s.id FROM students s JOIN ecosystem_links l ON l.student_id=s.id AND l.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.class_id=? AND l.user_id=? AND l.relation_type='parent' LIMIT 1",[$tid,(int)$p['class_id'],$uid]);
   if($role==='student'){$linked=cbStudentId($tid,$uid);return $linked>0&&(bool)g('SELECT id FROM students WHERE tenant_id=? AND class_id=? AND id=?',[$tid,(int)$p['class_id'],$linked]);}
   if($role==='teacher')return (bool)g('SELECT a.id FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.teacher_id=? AND a.class_id=? AND a.session_name=c.session_name LIMIT 1',[$tid,$uid,(int)$p['class_id']]);
   return false;
 }
 return false;
}
