    q('INSERT INTO cm_posts(tenant_id,author_id,title,body,audience,class_id,recipient_id,kind,pinned) VALUES(?,?,?,?,?,?,?,?,?)',[$cmTid,$cmUid,$title,$body,$aud,$aud==='class'?$cid:null,$aud==='person'?$rid:null,$kind,isset($_POST['pinned'])?1:0]);audit('communication.publish','cm_posts',$title);$cmNotice='Published to the selected audience.';
