    catch(Throwable $ex){q('INSERT INTO cm_email_log(tenant_id,post_id,recipient,status,error_message) VALUES(?,?,?,?,?)',[$cmTid,$id,$email,'failed',mb_substr($ex->getMessage(),0,255)]);throw $ex;}
    }
   }elseif($cmAction==='device'){
    $cmAdmin||throw new RuntimeException('Administrator required.');$name=mb_substr(trim((string)($_POST['device_name']??'')),0,120);if(mb_strlen($name)<3)throw new RuntimeException('Enter a device name.');
    $token=bin2hex(random_bytes(24));q('INSERT INTO cm_devices(tenant_id,device_name,token_hash,created_by) VALUES(?,?,?,?)',[$cmTid,$name,hash('sha256',$token),$cmUid]);$_SESSION['cm_device_token_once']=$token;$cmNotice='Scanner registered. Copy its token now; it is not stored in plain text.';
   }elseif($cmAction==='revoke'){
    $cmAdmin||throw new RuntimeException('Administrator required.');q('UPDATE cm_devices SET active=0 WHERE tenant_id=? AND id=?',[$cmTid,(int)($_POST['device_id']??0)]);$cmNotice='Scanner revoked.';
   }elseif($cmAction==='student_token'){
    $cmAdmin||throw new RuntimeException('Administrator required.');$sid=(int)($_POST['student_id']??0);if(!awOwnStudent($cmTid,$sid))throw new RuntimeException('Choose a student.');
    $token=bin2hex(random_bytes(20));q('UPDATE aw_scan_tokens SET active=0 WHERE tenant_id=? AND student_id=?',[$cmTid,$sid]);q('INSERT INTO aw_scan_tokens(tenant_id,student_id,token_hash) VALUES(?,?,?)',[$cmTid,$sid,hash('sha256',$token)]);$_SESSION['cm_student_token_once']=$token;$cmNotice='New student credential issued. Previous credentials revoked.';
   }elseif($cmAction==='scan'){
    $cmAdmin||throw new RuntimeException('School administrator scanning access required.');$device=trim((string)($_POST['device_token']??''));$student=trim((string)($_POST['student_token']??''));$method=(string)($_POST['method']??'manual');
