<?php if($lmView==='assignments'):?><div class="lm-card"><h3>Homework and submissions</h3><?php foreach($lmLessons as $l):if(!in_array($l['lesson_type'],['homework','quiz'],true))continue;?><div class="lm-card"><h3><?=e($l['title'])?></h3><p class="lm-muted">Maximum <?=e($l['points'])?> marks · <?=e($l['due_at']?'Due '.$l['due_at']:'No deadline')?></p><p><?=nl2br(e($l['content']))?></p><?php if($lmSid):?><?php $sub=q('SELECT score,feedback,submitted_at FROM lm_submissions WHERE tenant_id=? AND lesson_id=? AND student_id=?',[$lmTid,$l['id'],$lmSid])->fetch();if($sub):?><p class="lm-pill">Submitted <?=e($sub['submitted_at'])?> · <?=e($sub['score']===null?'Awaiting marking':'Score '.$sub['score'])?></p><?php if($sub['feedback']):?><p><?=e($sub['feedback'])?></p><?php endif;?><?php endif;?><form method="post" enctype="multipart/form-data" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><input type="hidden" name="lesson_id" value="<?=$l['id']?>"><label class="lm-wide">Your response<textarea name="answer" rows="3"></textarea></label><label>Attach PDF / image / text (max 3MB)<input type="file" name="attachment" accept=".pdf,.png,.jpg,.jpeg,.txt"></label><div class="lm-wide"><button class="btn" name="lm_action" value="submit">Submit assignment</button></div></form><?php endif;?><?php if($lmStaff):?><?php foreach(q('SELECT s.*,st.name student_name FROM lm_submissions s JOIN students st ON st.id=s.student_id AND st.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.lesson_id=? ORDER BY s.submitted_at DESC',[$lmTid,$l['id']])->fetchAll() as $sub):?><details><summary><?=e($sub['student_name'])?> · <?=e($sub['score']===null?'Not graded':$sub['score'].' marks')?></summary><p><?=nl2br(e($sub['answer']))?></p><?php if($sub['filename']):?><p class="lm-muted">Attachment: <?=e($sub['filename'])?> </p><a class="lm-link" href="?lm_file=<?=e($sub['id'])?>">Download attachment ↓</a><?php endif;?><form method="post" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><input type="hidden" name="submission_id" value="<?=$sub['id']?>"><label>Marks<input type="number" name="score" step="0.01" min="0" max="<?=e($l['points'])?>" value="<?=e($sub['score']??0)?>"></label><label>Feedback<input name="feedback" value="<?=e($sub['feedback'])?>"></label><div class="lm-wide"><button class="btn" name="lm_action" value="grade">Save grade</button></div></form></details><?php endforeach;?><?php endif;?></div><?php endforeach;?></div><?php endif;?>
<?php if($lmView==='discussions'):?><div class="lm-card"><h3>Moderated class discussions</h3><p class="lm-muted">Students' posts are reviewed by a teacher before appearing to the class.</p><?php foreach(q("SELECT d.*,u.name author FROM lm_discussions d JOIN users u ON u.id=d.user_id AND u.tenant_id=d.tenant_id WHERE d.tenant_id=? AND d.course_id=? AND (d.status='approved' OR ?=1) ORDER BY d.id DESC LIMIT 100",[$lmTid,$lmId,$lmStaff?1:0])->fetchAll() as $m):?><div class="lm-card"><strong><?=e($m['author'])?></strong> <span class="lm-tag"><?=e($m['status'])?></span><p><?=nl2br(e($m['message']))?></p><?php if($lmStaff&&$m['status']==='pending'):?><form method="post" class="lm-actions"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><input type="hidden" name="message_id" value="<?=$m['id']?>"><input type="hidden" name="lm_action" value="moderate"><button class="btn" name="decision" value="approve">Approve</button><button class="btn" name="decision" value="reject">Reject</button></form><?php endif;?></div><?php endforeach;?><form method="post" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><label class="lm-wide">New message<textarea name="message" rows="3" maxlength="3000" required></textarea></label><div><button class="btn" name="lm_action" value="discuss">Post message</button></div></form></div><?php endif;?>
<?php if($lmView==='live'):?><div class="lm-card"><h3>Live classroom</h3><p class="lm-muted">Join scheduled Zoom or Google Meet sessions. Sessions open in the provider's secure meeting experience.</p><?php foreach(q('SELECT * FROM lm_live WHERE tenant_id=? AND course_id=? ORDER BY starts_at DESC',[$lmTid,$lmId])->fetchAll() as $m):?><div class="lm-card"><span class="lm-tag"><?=e(strtoupper($m['provider']))?></span><h3><?=e($m['title'])?></h3><p class="lm-muted"><?=e($m['starts_at'].' – '.$m['ends_at'])?></p><a class="btn" target="_blank" rel="noopener noreferrer" href="<?=e($m['meeting_url'])?>">Join live class ↗</a></div><?php endforeach;?></div><?php if($lmStaff):?><div class="lm-card"><h3>Schedule a live class</h3><form method="post" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><label>Session title<input name="title" required></label><label>Platform<select name="provider"><option value="zoom">Zoom</option><option value="meet">Google Meet</option><option value="external">Other secure meeting link</option></select></label><label class="lm-wide">Meeting HTTPS link<input name="meeting_url" type="url" required></label><label>Starts<input name="starts_at" type="datetime-local" required></label><label>Ends<input name="ends_at" type="datetime-local" required></label><div class="lm-wide"><button class="btn" name="lm_action" value="live">Schedule live class</button></div></form></div><?php endif;?><?php endif;?>
<?php if($lmView==='groups'):?><div class="lm-card"><h3>Collaborative groups</h3><?php foreach(q('SELECT * FROM lm_groups WHERE tenant_id=? AND course_id=? ORDER BY id DESC',[$lmTid,$lmId])->fetchAll() as $group):?><div class="lm-card"><h3><?=e($group['name'])?></h3><p><?=nl2br(e($group['brief']))?></p><p class="lm-muted"><?=e($group['deadline']?'Deadline '.$group['deadline']:'Open-ended activity')?></p><?php foreach(q('SELECT s.name FROM lm_group_members gm JOIN students s ON s.id=gm.student_id AND s.tenant_id=gm.tenant_id WHERE gm.tenant_id=? AND gm.group_id=?',[$lmTid,$group['id']])->fetchAll() as $member):?><span class="lm-pill"><?=e($member['name'])?></span> <?php endforeach;?><?php if($lmStaff):?><form method="post" class="lm-form" style="margin-top:12px"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><input type="hidden" name="group_id" value="<?=$group['id']?>"><label>Add student<select name="student_id"><?php foreach(q('SELECT id,name FROM students WHERE tenant_id=? AND class_id=? ORDER BY name',[$lmTid,$lmCurrent['class_id']])->fetchAll() as $st):?><option value="<?=$st['id']?>"><?=e($st['name'])?></option><?php endforeach;?></select></label><div style="align-self:end"><button class="btn" name="lm_action" value="member">Add member</button></div></form><?php endif;?></div><?php endforeach;?></div><?php if($lmStaff):?><div class="lm-card"><h3>Create a group activity</h3><form method="post" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><label>Group name<input name="name" required></label><label>Deadline<input type="datetime-local" name="deadline"></label><label class="lm-wide">Group brief<textarea name="brief" rows="3"></textarea></label><div><button class="btn" name="lm_action" value="group">Create group</button></div></form></div><?php endif;?><?php endif;?>
<?php if($lmView==='progress'):?><div class="lm-card"><h3>Learning progress</h3><?php if($lmSid):?><h2><?=$lmPercent?>% completed</h2><div class="lm-progress"><i style="width:<?=$lmPercent?>%"></i></div><?php foreach(q('SELECT label,awarded_at FROM lm_badges WHERE tenant_id=? AND course_id=? AND student_id=? ORDER BY id DESC',[$lmTid,$lmId,$lmSid])->fetchAll() as $badge):?><p class="lm-pill">🏅 <?=e($badge['label'])?></p><?php endforeach;?><?php endif;?><?php if($lmStaff):?><?php foreach(q('SELECT id,name FROM students WHERE tenant_id=? AND class_id=? ORDER BY name',[$lmTid,$lmCurrent['class_id']])->fetchAll() as $st):$completed=(int)g('SELECT COUNT(*) FROM lm_progress p JOIN lm_lessons l ON l.id=p.lesson_id AND l.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.student_id=? AND l.course_id=?',[$lmTid,$st['id'],$lmId]);$pct=count($lmLessons)?round(100*$completed/count($lmLessons)):0;?><div class="lm-card"><strong><?=e($st['name'])?></strong><span class="lm-muted"> · <?=$pct?>% · <?=$completed?>/<?=count($lmLessons)?> activities</span><div class="lm-progress"><i style="width:<?=$pct?>%"></i></div></div><?php endforeach;?><details><summary>Award an achievement badge</summary><form method="post" class="lm-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="course_id" value="<?=$lmId?>"><label>Student<select name="student_id"><?php foreach(q('SELECT id,name FROM students WHERE tenant_id=? AND class_id=? ORDER BY name',[$lmTid,$lmCurrent['class_id']])->fetchAll() as $st):?><option value="<?=$st['id']?>"><?=e($st['name'])?></option><?php endforeach;?></select></label><label>Badge name<input name="label" placeholder="Outstanding participation" required></label><div class="lm-wide"><button class="btn" name="lm_action" value="badge">Award badge</button></div></form></details><?php endif;?></div><?php endif;?>
