<?php if($tab==='timetable'):?><div class="card ac-scroll"><h3>Scheduled lessons</h3><table class="table"><tr><th>Day</th><th>Time</th><th>Class</th><th>Subject</th><th>Room</th></tr><?php foreach(q('SELECT t.*,c.name class_name,s.name subject_name FROM ac_timetable t JOIN classes c ON c.id=t.class_id JOIN subjects s ON s.id=t.subject_id WHERE t.tenant_id=? ORDER BY weekday,start_time LIMIT 150',[$tid])->fetchAll() as $r):?><tr><td><?=e(['','Mon','Tue','Wed','Thu','Fri','Sat','Sun'][(int)$r['weekday']]??'')?></td><td><?=e($r['start_time'].'–'.$r['end_time'])?></td><td><?=e($r['class_name'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['room'])?></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='resources'):?><div class="card"><h3>Learning resources</h3><?php foreach(q('SELECT * FROM ac_resources WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll() as $r):?><p><a href="<?=e($r['url'])?>" target="_blank" rel="noopener noreferrer"><?=e($r['title'])?> ↗</a> <span class="muted"><?=e($r['notes'])?></span></p><?php endforeach;?></div><?php endif;?>
<?php if($tab==='assessments'):?><div class="card ac-scroll"><h3>Assessment components</h3><table class="table"><tr><th>Class / subject</th><th>Session / term</th><th>Component</th><th>Weight</th></tr><?php foreach($acAssess as $r):?><tr><td><?=e($r['class_name'].' / '.$r['subject_name'])?></td><td><?=e($r['session_name'].' · '.$r['term_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['weight'])?>%</td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='moderation'):?><div class="card ac-scroll"><h3>Review entered scores</h3><table class="table"><tr><th>Student</th><th>Assessment</th><th>Score</th><th>Status / moderation</th></tr><?php foreach(q('SELECT sc.*,st.name student_name,a.title assessment_name,a.max_score FROM ac_scores sc JOIN students st ON st.id=sc.student_id AND st.tenant_id=sc.tenant_id JOIN ac_assessments a ON a.id=sc.assessment_id AND a.tenant_id=sc.tenant_id WHERE sc.tenant_id=? ORDER BY sc.updated_at DESC LIMIT 150',[$tid])->fetchAll() as $r):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['assessment_name'])?></td><td><?=e($r['score'].' / '.$r['max_score'])?></td><td><form method="post" style="display:flex;gap:6px;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach(['draft','submitted','approved'] as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach;?></select><input name="moderation_note" maxlength="500" placeholder="Review note" value="<?=e($r['moderation_note'])?>"><button class="btn" name="ac_action" value="moderate">Save</button></form></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='reports'):?><div class="card"><h3>Publish term results</h3><p class="ac-help">Publication requires every recorded score to be approved and each subject's assessment weights to total 100%.</p><form class="ac-form" method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Class<select name="class_id" required><?php foreach($acClasses as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Session<input name="session_name" placeholder="2026/2027" required></label><label>Term<input name="term_name" placeholder="First Term" required></label><div class="wide"><button class="btn" name="ac_action" value="publish">Approve & publish</button></div></form></div><div class="card ac-scroll"><h3>Published reports</h3><table class="table"><tr><th>Class</th><th>Session / term</th><th>Published</th><th>Student reports</th></tr><?php foreach(q("SELECT a.*,c.name class_name FROM ac_term_approvals a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.status='published' ORDER BY a.id DESC LIMIT 40",[$tid])->fetchAll() as $r):?><tr><td><?=e($r['class_name'])?></td><td><?=e($r['session_name'].' · '.$r['term_name'])?></td><td><?=e($r['published_at'])?></td><td><?php foreach($acStudents as $st){if((int)$st['class_id']!==(int)$r['class_id'])continue;?><a style="display:inline-block;margin:3px" target="_blank" rel="noopener" href="?ac_pdf=report&amp;class=<?=$r['class_id']?>&amp;session=<?=urlencode($r['session_name'])?>&amp;term=<?=urlencode($r['term_name'])?>&amp;student=<?=$st['id']?>"><?=e($st['name'])?> ↗</a><?php }?></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='rankings'):?>
<div class="card"><h3>Published class rankings</h3><p class="ac-help">Ranks use the mean of approved weighted subject totals. Equal averages share a rank. Only published terms are shown.</p><form method="get" class="ac-form"><input type="hidden" name="s" value="academics"><input type="hidden" name="tab" value="rankings"><label>Published term<select name="term_id"><?php foreach(q("SELECT a.id,a.class_id,a.session_name,a.term_name,c.name class_name FROM ac_term_approvals a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.status='published' ORDER BY a.id DESC",[$tid])->fetchAll() as $r):?><option value="<?=$r['id']?>" <?=(int)($_GET['term_id']??0)===(int)$r['id']?'selected':''?>><?=e($r['class_name'].' · '.$r['session_name'].' · '.$r['term_name'])?></option><?php endforeach;?></select></label><button class="btn">Show rankings</button></form>
<?php $selected=(int)($_GET['term_id']??0);$chosen=q("SELECT * FROM ac_term_approvals WHERE id=? AND tenant_id=? AND status='published'",[$selected,$tid])->fetch();if($chosen):?><table class="table"><tr><th>Rank</th><th>Student</th><th>Subjects</th><th>Average</th></tr><?php foreach(acClassRankings($tid,(int)$chosen['class_id'],$chosen['session_name'],$chosen['term_name']) as $r):?><tr><td><?=$r['rank']?></td><td><?=e($r['name'])?></td><td><?=$r['subjects']?></td><td><?=number_format($r['average'],2)?>%</td></tr><?php endforeach;?></table><?php endif;?></div>
<?php endif;?>
<?php if($tab==='transcripts'):?><div class="card"><h3>Student academic transcripts</h3><p class="ac-help">Generate a consolidated transcript from approved and published results across previous classes and sessions. Print or save as PDF.</p><table class="table"><tr><th>Student</th><th>Transcript</th></tr><?php foreach($acStudents as $r):?><tr><td><?=e($r['name'])?></td><td><a href="?ac_pdf=transcript&amp;student=<?=$r['id']?>" target="_blank" rel="noopener">Open transcript ↗</a></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='promotion'):?><div class="card"><h3>Promote a student</h3><p class="ac-help">Promotions require a published term for the originating session. Each student may be promoted only once into a given session; previous results are preserved.</p><form method="post" class="ac-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label>Student<select name="student_id" required><?php foreach($acStudents as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Destination class<select name="to_class_id" required><?php foreach($acClasses as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>From session<input name="from_session" required placeholder="2026/2027"></label><label>To session<input name="to_session" required placeholder="2027/2028"></label><div class="wide"><button class="btn" name="ac_action" value="promote" onclick="return confirm('Promote this student? The current class will change and an audit record will be kept.')">Confirm promotion</button></div></form></div><div class="card ac-scroll"><h3>Promotion history</h3><table class="table"><tr><th>Student</th><th>From → To</th><th>Session</th><th>Approved</th></tr><?php foreach(q('SELECT p.*,st.name student_name,fc.name from_name,tc.name to_name FROM ac_promotions p JOIN students st ON st.id=p.student_id AND st.tenant_id=p.tenant_id JOIN classes fc ON fc.id=p.from_class_id AND fc.tenant_id=p.tenant_id JOIN classes tc ON tc.id=p.to_class_id AND tc.tenant_id=p.tenant_id WHERE p.tenant_id=? ORDER BY p.id DESC LIMIT 100',[$tid])->fetchAll() as $r):?><tr><td><?=e($r['student_name'])?></td><td><?=e($r['from_name'].' → '.$r['to_name'])?></td><td><?=e($r['from_session'].' → '.$r['to_session'])?></td><td><?=e($r['approved_at'])?></td></tr><?php endforeach;?></table></div><?php endif;?>
<?php if($tab==='analytics'):?><div class="ac-metrics"><?php foreach(['Subjects'=>'subjects','Students'=>'students','Approved scores'=>'ac_scores','Completed syllabus topics'=>'ac_curriculum'] as $label=>$table):?><div class="card"><div class="muted"><?=e($label)?></div><div class="num"><?php if($table==='ac_scores')echo (int)g("SELECT COUNT(*) FROM ac_scores WHERE tenant_id=? AND status='approved'",[$tid]);elseif($table==='ac_curriculum')echo (int)g("SELECT COUNT(*) FROM ac_curriculum WHERE tenant_id=? AND coverage='completed'",[$tid]);else echo (int)g("SELECT COUNT(*) FROM `$table` WHERE tenant_id=?",[$tid]);?></div></div><?php endforeach;?></div><div class="card ac-scroll"><h3>Published class performance</h3><p class="ac-help">Average across students with approved scores in published terms.</p><table class="table"><tr><th>Class</th><th>Session</th><th>Term</th><th>Students with results</th><th>Class mean</th></tr><?php foreach(q("SELECT a.*,c.name class_name FROM ac_term_approvals a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.status='published' ORDER BY a.id DESC LIMIT 80",[$tid])->fetchAll() as $t):$rankings=acClassRankings($tid,(int)$t['class_id'],$t['session_name'],$t['term_name']);$mean=count($rankings)?array_sum(array_column($rankings,'average'))/count($rankings):0;?><tr><td><?=e($t['class_name'])?></td><td><?=e($t['session_name'])?></td><td><?=e($t['term_name'])?></td><td><?=count($rankings)?></td><td><?=number_format($mean,2)?>%</td></tr><?php endforeach;?></table></div><?php endif;?>
<?php endif;?><?php endif;?></div>
<?php elseif($section==='exams'):?>
<?php $cbActive=cbReady();$cbTab=(string)($_GET['tab']??(isset($_GET['exam'])?'questions':'overview'));if(!in_array($cbTab,['overview','create','questions','marking'],true))$cbTab='overview';$cbExamId=(int)($_GET['exam']??0);$cbAttemptId=(int)($_GET['attempt']??0);$cbExam=$cbActive&&$cbExamId?cbExam($tid,$cbExamId):null;$cbAttempt=$cbActive&&$cbAttemptId?cbAttempt($tid,$cbAttemptId):null;$cbIsAdmin=$cbAdmin;$cbIsStudent=$cbLearner;$cbStudent=$cbIsStudent?cbStudentId($tid,(int)$u['id']):0;$cbExams=$cbActive?q('SELECT x.*,c.name class_name,s.name subject_name,(SELECT COUNT(*) FROM cb_questions qq WHERE qq.tenant_id=x.tenant_id AND qq.exam_id=x.id) question_count,(SELECT COUNT(*) FROM cb_attempts aa WHERE aa.tenant_id=x.tenant_id AND aa.exam_id=x.id) attempt_count FROM cb_exams x JOIN classes c ON c.id=x.class_id AND c.tenant_id=x.tenant_id JOIN subjects s ON s.id=x.subject_id AND s.tenant_id=x.tenant_id WHERE x.tenant_id=? ORDER BY x.id DESC',[$tid])->fetchAll():[]; ?>
