b-alert{padding:12px 15px;border-radius:12px;background:#edf5fc;border:1px solid #c6dfef;color:#174665}@media(max-width:700px){.cb-form{grid-template-columns:1fr}.cb-statrow{grid-template-columns:repeat(2,1fr)}.cb-hero{padding:20px}}
 .cb-exam-picker{display:grid;gap:10px;margin-top:16px}.cb-picker-item{display:flex;gap:12px;align-items:center;flex-wrap:wrap;border:1px solid var(--line);border-radius:12px;padding:15px;text-decoration:none;color:var(--ink)}.cb-picker-item span{color:var(--sub);font-size:12px;flex:1}.cb-picker-item b{color:#087e77;font-size:13px}.cb-workspace-header{display:flex;justify-content:space-between;align-items:center;gap:15px}.cb-back{display:inline-block;font-size:12px;margin-bottom:12px;color:var(--sub)}.cb-bank{max-width:920px}.cb-question-editor{max-width:820px}.cb-bank-list{margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}.cb-manage{display:inline-block;padding:9px 12px;background:#e4f5f1;border-radius:9px;color:#086c5c!important;font-weight:750;white-space:nowrap}.cb-question-editor textarea{min-height:80px}.cb-question-editor .wide textarea[name="body"]{min-height:95px}@media(max-width:700px){.cb-picker-item{display:grid}.cb-workspace-header{align-items:flex-start}}
</style>
<div class="cb"><div class="cb-hero"><h2>CBT & Examinations</h2><p><?= $cbIsStudent?'Take scheduled assessments, resume interrupted attempts and view published results.':'Build assessments, deliver secure timed exams, grade scripts and publish results.' ?></p></div>
<?php if($cbNotice!==''):?><div class="cb-alert" role="status"><?=e($cbNotice)?></div><?php endif;?>
<?php if(!$cbActive):?><div class="cb-panel"><h3>Activate examination workspace</h3><p class="cb-muted">Creates exam, question, attempt, grading and audit tables without deleting existing records.</p><?php if($cbIsAdmin):?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><button class="btn" name="cb_action" value="install">Activate CBT</button></form><?php else:?>Ask your school administrator to activate CBT.<?php endif;?></div>
<?php else:?>
<?php if($cbIsAdmin):?><nav class="cb-tabs"><a class="<?=$cbTab==='overview'?'active':''?>" href="?s=exams">Overview</a><a class="<?=$cbTab==='create'?'active':''?>" href="?s=exams&tab=create">Create exam</a><a class="<?=$cbTab==='questions'?'active':''?>" href="?s=exams&tab=questions<?= $cbExamId?'&amp;exam='.$cbExamId:'' ?>">Question banks</a><a class="<?=$cbTab==='marking'?'active':''?>" href="?s=exams&tab=marking">Marking & results</a></nav><?php endif;?>
<?php if($cbIsStudent&&$cbAttempt):?>
<?php if((int)$cbAttempt['user_id']!==(int)$u['id']):?><div class="cb-panel">Attempt unavailable.</div>
<?php elseif($cbAttempt['submitted_at']):?><div class="cb-panel"><h3>Attempt submitted</h3><p>Your answers have been recorded. <?php $exam=cbExam($tid,(int)$cbAttempt['exam_id']);if($exam['results_published']):?>Score: <?=e($cbAttempt['score'])?> / <?=e($cbAttempt['max_score'])?>.<?php else:?>Results will appear after publication.<?php endif;?></p><a class="btn" href="?s=exams">Back to exams</a></div>
<?php else:?><?php $exam=cbExam($tid,(int)$cbAttempt['exam_id']);$order=json_decode($cbAttempt['question_order_json'],true)?:[];$questions=q('SELECT q.*,a.response FROM cb_questions q JOIN cb_answers a ON a.question_id=q.id AND a.tenant_id=q.tenant_id WHERE a.tenant_id=? AND a.attempt_id=?',[$tid,$cbAttemptId])->fetchAll();$byId=[];foreach($questions as $question)$byId[$question['id']]=$question; ?>
<div class="cb-timer"><span><?=e($exam['title'])?></span><span id="cbClock" data-expiry="<?=e(date('c',strtotime($cbAttempt['expires_at'])))?>">Calculating time…</span></div>
<form method="post" id="cbExamForm" class="cb-questions"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="attempt_id" value="<?=$cbAttemptId?>">
<?php foreach($order as $i=>$qid):if(!isset($byId[$qid]))continue;$question=$byId[$qid];$opts=json_decode($question['options_json']??'[]',true)?:[];if($exam['randomize']){mt_srand((int)$cbAttemptId+(int)$qid);shuffle($opts);mt_srand();}?>
<section class="cb-question"><strong>Question <?=$i+1?> <span class="cb-muted">· <?=e($question['points'])?> marks · <?=e(strtoupper($question['kind']))?></span></strong><p><?=nl2br(e($question['body']))?></p><?php if($question['media_url']):?><p><a href="<?=e($question['media_url'])?>" target="_blank" rel="noopener noreferrer">Open question media ↗</a></p><?php endif;?>
<?php if(in_array($question['kind'],['mcq','truefalse'],true)):foreach(($question['kind']==='truefalse'?['True','False']:$opts) as $option):?><label class="cb-option"><input type="radio" name="answers[<?=$qid?>]" value="<?=e($option)?>" <?=($question['response']??'')===$option?'checked':''?>> <?=e($option)?></label><?php endforeach;else:?><textarea class="cb-answer" rows="<?=$question['kind']==='essay'?7:3?>" name="answers[<?=$qid?>]" placeholder="Write your answer here…"><?=e($question['response']??'')?></textarea><?php endif;?></section>
<?php endforeach;?><div class="cb-panel cb-actions"><button class="btn" name="cb_action" value="save">Save & continue later</button><button class="btn" style="background:#125b43" name="cb_action" value="submit" onclick="return confirm('Submit your final answers? You cannot edit after submission.')">Submit exam</button><span class="cb-muted">Answers are saved when you press Save. The timer continues if you leave.</span></div></form>
<script>(function(){const el=document.getElementById('cbClock'),form=document.getElementById('cbExamForm');if(!el||!form)return;let expired=false;function tick(){let left=Math.max(0,Math.floor((new Date(el.dataset.expiry).getTime()-Date.now())/1000));el.textContent=Math.floor(left/60)+'m '+String(left%60).padStart(2,'0')+'s remaining';if(!left&&!expired){expired=true;const b=document.createElement('input');b.type='hidden';b.name='cb_action';b.value='submit';form.appendChild(b);form.submit()}}tick();setInterval(tick,1000);let changes=0;document.addEventListener('visibilitychange',()=>{if(document.hidden)changes++});window.addEventListener('beforeunload',()=>{if(changes&&navigator.sendBeacon){const fd=new FormData();fd.set('csrf',form.querySelector('[name=csrf]').value);fd.set('cb_action','integrity');fd.set('attempt_id',form.querySelector('[name=attempt_id]').value);fd.set('event','Tab/background switches: '+changes);navigator.sendBeacon(location.href,fd)}})})();</script>
<?php endif;?>
<?php elseif($cbIsStudent):?><div class="cb-panel"><h3>Available exams</h3><p class="cb-muted">Enter your exam code if provided. A timer starts when you begin and continues across interruptions.</p><?php if(!$cbStudent):?><div class="cb-alert">Your student login must be linked to your student record by the school administrator.</div><?php endif;?><?php foreach($cbExams as $exam):if(!$exam['published']||!$cbStudent||(int)$exam['class_id']!==(int)g('SELECT class_id FROM students WHERE tenant_id=? AND id=?',[$tid,$cbStudent]))continue;$active=q("SELECT id FROM cb_attempts WHERE tenant_id=? AND exam_id=? AND student_id=? AND submitted_at IS NULL ORDER BY id DESC LIMIT 1",[$tid,$exam['id'],$cbStudent])->fetchColumn();?><div class="cb-question"><strong><?=e($exam['title'])?></strong><p class="cb-muted"><?=e($exam['subject_name'])?> · <?=e($exam['duration_minutes'])?> minutes · <?=e($exam['question_count'])?> questions · <?=e(strtoupper($exam['mode']))?></p><?php if($active):?><a class="btn" href="?s=exams&attempt=<?=$active?>">Resume exam</a><?php else:?><form method="post" class="cb-actions"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="exam_id" value="<?=$exam['id']?>"><?php if($exam['access_code']!==''):?><input class="cb-answer" style="width:170px" name="code" placeholder="Exam code" required><?php endif;?><button class="btn" name="cb_action" value="start">Start exam</button></form><?php endif;?><?php if($exam['results_published']):?><?php foreach(q('SELECT score,max_score,status FROM cb_attempts WHERE tenant_id=? AND exam_id=? AND student_id=? AND submitted_at IS NOT NULL',[$tid,$exam['id'],$cbStudent])->fetchAll() as $res):?><p class="cb-muted">Published result: <?=e($res['score'])?> / <?=e($res['max_score'])?> (<?=e($res['status'])?>)</p><?php endforeach;?><?php endif;?></div><?php endforeach;?></div>
<?php elseif($cbIsAdmin):?>
<?php if($cbTab==='create'):?><div class="cb-panel"><h3>Create a new examination</h3><p class="cb-muted">Step 1: Set the class, subject, mode and rules. Step 2: Add questions. Step 3: Publish when ready.</p><form method="post" class="cb-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><label class="wide">Exam title<input name="title" placeholder="e.g. JSS 2 Mathematics — First Term" required></label><label>Class<select name="class_id" required><?php foreach(q('SELECT id,name,section FROM classes WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll() as $r):?><option value="<?=$r['id']?>"><?=e($r['name'].' '.$r['section'])?></option><?php endforeach;?></select></label><label>Subject<select name="subject_id" required><?php foreach(q('SELECT id,name FROM subjects WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll() as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Exam format<select name="mode"><option value="school">School assessment</option><option value="waec">WAEC-style mock</option><option value="neco">NECO-style mock</option><option value="jamb">JAMB-style mock</option></select></label><label>Duration (minutes)<input type="number" name="minutes" min="1" max="300" value="45"></label><label>Attempt limit<input type="number" name="limit" min="1" max="20" value="1"></label><label>Questions per attempt (0 = all)<input type="number" name="question_limit" min="0" value="0"></label><label>Pass percentage<input type="number" name="pass" min="0" max="100" value="50"></label><label>Exam access code (optional)<input name="code" autocomplete="off"></label><label class="wide"><span><input type="checkbox" name="randomize" checked> Randomize question and option order</span></label><div class="wide"><button class="btn" name="cb_action" value="exam">Create examination</button></div></form></div>
