<div class="cb-panel cb-bank" id="cb-question-editor"><h3>Add & manage questions</h3><p class="cb-muted">Supports MCQ, true/false, short answers, essays, equation text and HTTPS multimedia links. For equations, enter readable mathematical notation in the question text.</p><form method="post" class="cb-actions"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="exam_id" value="<?=$cbExamId?>"><label><input type="checkbox" name="enabled" <?=$cbExam['published']?'checked':''?>> Allow students to take this exam</label><button class="btn" name="cb_action" value="publish">Save availability</button></form><?php if(!$cbExam['published']):?><form method="post" class="cb-form cb-question-editor" style="margin-top:16px"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="exam_id" value="<?=$cbExamId?>"><label>Question type<select name="kind"><option value="mcq">Multiple choice</option><option value="truefalse">True / false</option><option value="short">Short answer</option><option value="essay">Essay</option></select></label><label>Maximum marks<input name="points" type="number" step="0.1" min="0.1" value="1"></label><label class="wide">Question text / equation<textarea name="body" rows="3" required></textarea></label><label class="wide">Options (MCQ: one per line)<textarea name="options" rows="4"></textarea></label><label>Correct answer (exact MCQ option or True / False)<input name="correct"></label><label>Media URL (HTTPS)<input name="media_url" type="url" placeholder="https://..."></label><label class="wide">Marking guidance / explanation<textarea name="explanation" rows="2"></textarea></label><div class="wide"><button class="btn" name="cb_action" value="question">Add question</button></div></form><details style="margin-top:15px"><summary>Import questions from CSV</summary><p class="cb-muted">Columns: kind,body,options,correct,points,explanation. Separate MCQ options with |. Maximum 500 rows / 1 MB.</p><form method="post" enctype="multipart/form-data" class="cb-actions"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="exam_id" value="<?=$cbExamId?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn" name="cb_action" value="import">Import CSV</button></form></details><?php else:?><p class="cb-alert">Unpublish this exam to add or import questions.</p><?php endif;?><div id="cb-question-list" class="cb-bank-list"><h3>Saved questions</h3><p class="cb-muted">Review the question bank before publishing.</p><?php foreach(q('SELECT * FROM cb_questions WHERE tenant_id=? AND exam_id=? ORDER BY id',[$tid,$cbExamId])->fetchAll() as $i=>$question):?><div class="cb-question"><strong><?=($i+1)?>. <?=e($question['body'])?></strong><p class="cb-muted"><?=e(strtoupper($question['kind']))?> · <?=e($question['points'])?> marks</p></div><?php endforeach;?></div></div>
