<?php if($cbAttempt&&$cbExam&&(int)$cbAttempt['exam_id']===$cbExamId):?><div class="cb-panel"><h3>Script #<?=$cbAttemptId?> · Marking and remarking</h3><?php foreach(q('SELECT a.*,q.body,q.kind,q.points FROM cb_answers a JOIN cb_questions q ON q.id=a.question_id AND q.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.attempt_id=?',[$tid,$cbAttemptId])->fetchAll() as $ans):?><div class="cb-question"><strong><?=e($ans['body'])?></strong><p><?=nl2br(e($ans['response']??'(no answer)'))?></p><p class="cb-muted">Awarded <?=e($ans['awarded']??'Pending')?> / <?=e($ans['points'])?></p><?php if(in_array($ans['kind'],['short','essay'],true)&&$cbAttempt['submitted_at']):?><form method="post" class="cb-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="attempt_id" value="<?=$cbAttemptId?>"><input type="hidden" name="answer_id" value="<?=$ans['id']?>"><label>Marks (partial credit allowed)<input type="number" name="awarded" min="0" max="<?=e($ans['points'])?>" step="0.1" value="<?=e($ans['awarded']??0)?>"></label><label>Feedback<input name="feedback" placeholder="Marker feedback"></label><div><button class="btn" name="cb_action" value="grade">Save grade</button></div></form><?php endif;?><?php if($cbAttempt['submitted_at']):?><details><summary>Remark this answer</summary><form method="post" class="cb-form"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="attempt_id" value="<?=$cbAttemptId?>"><input type="hidden" name="answer_id" value="<?=$ans['id']?>"><label>Revised marks<input type="number" name="awarded" min="0" max="<?=e($ans['points'])?>" step="0.1" value="<?=e($ans['awarded']??0)?>"></label><label>Reason<input name="reason" minlength="8" required></label><div><button class="btn" name="cb_action" value="remark">Record remark</button></div></form></details><?php endif;?></div><?php endforeach;?></div><div class="cb-panel"><h3>Integrity & audit history</h3><?php foreach(q('SELECT event_type,details,created_at FROM cb_events WHERE tenant_id=? AND attempt_id=? ORDER BY id DESC LIMIT 100',[$tid,$cbAttemptId])->fetchAll() as $log):?><p class="cb-muted"><?=e($log['created_at'].' · '.$log['event_type'].' · '.$log['details'])?></p><?php endforeach;?></div><?php endif;?>
