<?php elseif($cmTab==='scanner'&&$cmAdmin):?><div class="cm-panel"><h2>Registered attendance scanners</h2><p class="cm-hint">Register a scanner, issue a revocable student credential, then scan using the camera (where supported) or enter the credential. Every scan is audited.</p><div class="cm-two"><form method="post" class="cm-form" style="grid-template-columns:1fr"><?=$cmHidden?><input type="hidden" name="cm_action" value="device"><label>Scanner name<input name="device_name" required placeholder="Main gate tablet"></label><button class="cm-action">Register device</button></form><form method="post" class="cm-form" style="grid-template-columns:1fr"><?=$cmHidden?><input type="hidden" name="cm_action" value="student_token"><label>Issue student QR / NFC credential<select name="student_id" required><option value="">Select student</option><?php foreach(q('SELECT id,name,student_no FROM students WHERE tenant_id=? ORDER BY name LIMIT 1500',[$tid])->fetchAll() as $student):?><option value="<?=$student['id']?>"><?=e($student['name'].' · '.$student['student_no'])?></option><?php endforeach;?></select></label><button class="cm-action">Issue / rotate credential</button></form></div><?php if(isset($_SESSION['cm_device_token_once'])):?><p><strong>Device token — copy now:</strong> <code><?=e($_SESSION['cm_device_token_once'])?></code></p><?php unset($_SESSION['cm_device_token_once']);endif;?><?php if(isset($_SESSION['cm_student_token_once'])):?><p><strong>Student QR/NFC credential — copy now:</strong> <code id="cmCredential"><?=e($_SESSION['cm_student_token_once'])?></code></p><div id="cmQrImage" class="cm-hint">Encode this credential as a QR code using your approved ID-card system; the scanner also accepts the token directly.</div><?php unset($_SESSION['cm_student_token_once']);endif;?><h3>Check in student</h3><form method="post" class="cm-form" id="cmScanForm"><?=$cmHidden?><input type="hidden" name="cm_action" value="scan"><label>Registered device token<input name="device_token" minlength="48" maxlength="48" required autocomplete="off" placeholder="Paste registered scanner token"></label><label>Student credential<input name="student_token" id="cmStudentScan" minlength="40" maxlength="40" required autocomplete="off" placeholder="Scan or enter student credential"></label><label>Scan method<select name="method" id="cmMethod"><option value="manual">Manual</option><option value="qr">QR camera</option><option value="nfc">NFC</option></select></label><div style="align-self:end"><button class="cm-action">Confirm check-in</button></div></form><div class="cm-compact" style="margin-top:12px"><button type="button" class="cm-action" id="cmCamera">Scan QR using camera</button><button type="button" class="cm-action" id="cmNfc">Read NFC tag</button><span class="cm-hint" id="cmScanStatus"></span></div><video id="cmVideo" playsinline muted style="display:none;width:min(100%,400px);margin-top:12px;border-radius:12px"></video><script>(function(){const input=document.getElementById('cmStudentScan'),msg=document.getElementById('cmScanStatus'),video=document.getElementById('cmVideo');document.getElementById('cmCamera').onclick=async()=>{if(!('BarcodeDetector'in window)||!navigator.mediaDevices){msg.textContent='Camera QR scanning is unavailable on this browser. Use the credential field.';return;}let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=stream;video.style.display='block';await video.play();const detector=new BarcodeDetector({formats:['qr_code']});let active=true;const scan=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes.length&&/^[a-f0-9]{40}$/.test(codes[0].rawValue)){input.value=codes[0].rawValue;document.getElementById('cmMethod').value='qr';active=false;stream.getTracks().forEach(t=>t.stop());video.style.display='none';msg.textContent='QR scanned. Confirm check-in.';return;}}catch(e){}requestAnimationFrame(scan)};scan();}catch(e){if(stream)stream.getTracks().forEach(t=>t.stop());msg.textContent='Camera permission denied or unavailable.';}};document.getElementById('cmNfc').onclick=async()=>{if(!('NDEFReader'in window)){msg.textContent='Web NFC is not supported on this browser/device.';return;}try{const reader=new NDEFReader();await reader.scan();msg.textContent='Hold the student NFC tag near this device.';reader.onreading=event=>{for(const record of event.message.records){if(record.recordType==='text'){const value=new TextDecoder(record.encoding||'utf-8').decode(record.data);if(/^[a-f0-9]{40}$/.test(value)){input.value=value;document.getElementById('cmMethod').value='nfc';msg.textContent='NFC credential read. Confirm check-in.';break;}}}};}catch(e){msg.textContent='NFC permission denied or unavailable.';}};})();</script><h3>Registered devices</h3><?php foreach(q('SELECT id,device_name,active,created_at FROM cm_devices WHERE tenant_id=? ORDER BY id DESC',[$tid])->fetchAll() as $d):?><div class="cm-compact" style="padding:8px 0;border-bottom:1px solid var(--line)"><strong><?=e($d['device_name'])?></strong><span class="cm-hint"><?=e($d['active']?'Active':'Revoked')?></span><?php if($d['active']):?><form method="post"><?=$cmHidden?><input type="hidden" name="cm_action" value="revoke"><input type="hidden" name="device_id" value="<?=$d['id']?>"><button>Revoke</button></form><?php endif;?></div><?php endforeach;?></div>
<?php elseif($cmTab==='email'&&$cmAdmin):?><div class="cm-panel"><h2>SMTP activity</h2><p class="cm-hint">Use Integrations to configure and test SMTP. Each send is initiated by an administrator and logged; messages are never marked sent before SMTP accepts them.</p><div style="overflow:auto"><table class="table"><tr><th>Recipient</th><th>Status</th><th>Time</th><th>Details</th></tr><?php foreach(q('SELECT * FROM cm_email_log WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll() as $log):?><tr><td><?=e($log['recipient'])?></td><td><?=e($log['status'])?></td><td><?=e($log['created_at'])?></td><td><?=e($log['error_message'])?></td></tr><?php endforeach;?></table></div></div>
