<?php if($post['kind']==='discussion'):?><h4>Discussion</h4><?php foreach(q("SELECT c.*,u.name FROM cm_comments c JOIN users u ON u.id=c.author_id AND u.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.post_id=? ORDER BY c.id",[$tid,$post['id']])->fetchAll() as $comment):if($comment['status']!=='approved'&&!$cmAdmin&&(int)$comment['author_id']!==$cmUid)continue;?><div style="border-top:1px solid var(--line);padding:10px 0"><strong><?=e($comment['name'])?></strong> <span class="cm-hint"><?=e($comment['status'])?></span><p><?=e($comment['body'])?></p><?php if($cmAdmin&&$comment['status']==='pending'):?><form method="post" class="cm-compact"><?=$cmHidden?><input type="hidden" name="cm_action" value="moderate"><input type="hidden" name="comment_id" value="<?=$comment['id']?>"><button name="decision" value="approved">Approve</button><button name="decision" value="rejected">Reject</button></form><?php endif;?></div><?php endforeach;?><form method="post" class="cm-form"><?=$cmHidden?><input type="hidden" name="cm_action" value="comment"><input type="hidden" name="post_id" value="<?=$post['id']?>"><label class="cm-wide">Write a reply<textarea name="body" rows="2" required></textarea></label><div><button class="cm-action">Submit reply</button></div></form><?php endif;?></article><?php endforeach;if(!$visible):?><div class="cm-panel">No community posts for your account yet. School administrators can publish the first announcement.</div><?php endif;?></div>
