<div class="aw-panel"><h2>Active case register</h2><div class="aw-scroll"><table class="aw-table"><tr><th>Student</th><th>Type</th><th>Case</th><th>Status</th><th>Follow-up</th></tr><?php foreach(q("SELECT c.*,s.name FROM aw_cases c JOIN students s ON s.id=c.student_id AND s.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.status<>'closed' ORDER BY c.id DESC LIMIT 70",[$tid])->fetchAll() as $r):if($r['confidential']&&!$awAdmin)continue;?><tr><td><?=e($r['name'])?></td><td><?=e($r['kind'])?></td><td><?=e($r['title'])?></td><td><?=e($r['status'])?></td><td><details><summary>Update</summary><form method="post"><?=$awHidden?><input type="hidden" name="aw_action" value="case_note"><input type="hidden" name="case_id" value="<?=$r['id']?>"><textarea name="note" required placeholder="Case follow-up notes"></textarea><label><input type="checkbox" name="close" value="1"> Close case</label><button class="aw-btn">Save update</button></form><?php if($awAdmin):?><form method="post"><?=$awHidden?><input type="hidden" name="aw_action" value="escalate"><input type="hidden" name="case_id" value="<?=$r['id']?>"><input name="contact_name" placeholder="Emergency contact" required><input name="contact_phone" placeholder="Contact phone" required><textarea name="action_taken" placeholder="Action taken and escalation details" required></textarea><button class="aw-btn">Log emergency escalation</button></form><?php endif;?></details></td></tr><?php endforeach;?></table></div></div>
<?php elseif($awTab==='sickbay'):?>
<?php if(!$awAdmin):?><div class="aw-panel"><h2>Restricted health records</h2><p>Only authorised school administrators can view or manage sick bay and medication information in this release.</p></div><?php else:?>
<div class="aw-warning">Medical records are sensitive. Obtain documented consent and restrict access. This workspace does not replace medical advice or emergency response.</div>
<div class="aw-panel"><h2>New sick bay visit</h2><form method="post" class="aw-form"><?=$awHidden?><input type="hidden" name="aw_action" value="sickbay"><label>Learner<?php $awStudentSelect();?></label><label>Presenting complaint<textarea name="complaint" required></textarea></label><label class="aw-wide">Care provided<textarea name="care_given"></textarea></label><div><button class="aw-btn">Record visit</button></div></form></div>
<div class="aw-panel"><h2>Medication administration register</h2><p>Record medication only after checking the student's documented authorisation and school policy.</p><form method="post" class="aw-form"><?=$awHidden?><input type="hidden" name="aw_action" value="medication"><label>Learner<?php $awStudentSelect();?></label><label>Medication<input name="medication" required></label><label>Dose administered<input name="dose" required></label><label>Written authorisation reference<input name="authorisation_ref" required></label><label class="aw-wide">Notes<textarea name="notes"></textarea></label><div><button class="aw-btn">Log administration</button></div></form></div>
<div class="aw-panel"><h2>Recent health visits</h2><div class="aw-scroll"><table class="aw-table"><tr><th>Date</th><th>Student</th><th>Complaint</th><th>Care</th></tr><?php foreach(q('SELECT h.*,s.name FROM aw_sickbay h JOIN students s ON s.id=h.student_id AND s.tenant_id=h.tenant_id WHERE h.tenant_id=? ORDER BY h.id DESC LIMIT 30',[$tid])->fetchAll() as $r):?><tr><td><?=e($r['arrived_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['complaint'])?></td><td><?=e($r['care_given'])?></td></tr><?php endforeach;?></table></div></div><?php endif;?>
<?php elseif($awTab==='alerts'):?>
<div class="aw-panel"><h2>Parent attendance alerts</h2><p>Absent and late marks create alerts for staff review. No SMS, WhatsApp or email is automatically sent without a configured messaging provider.</p><div class="aw-scroll"><table class="aw-table"><tr><th>Created</th><th>Student</th><th>Message</th><th>Status</th><th>Action</th></tr><?php foreach(q('SELECT a.*,s.name FROM aw_alerts a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? ORDER BY a.id DESC LIMIT 100',[$tid])->fetchAll() as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name'])?></td><td><?=e($r['message'])?></td><td><?=e($r['status'])?></td><td><?php if($awAdmin&&sisReady()):$gphone=(string)g('SELECT g.phone FROM sis_guardians g JOIN sis_student_guardians sg ON sg.guardian_id=g.id AND sg.tenant_id=g.tenant_id WHERE sg.tenant_id=? AND sg.student_id=? ORDER BY sg.primary_contact DESC LIMIT 1',[$tid,$r['student_id']]);$wa=cmPhone($gphone);if($wa):?><a target="_blank" rel="noopener noreferrer" href="https://wa.me/<?=e($wa)?>?text=<?=rawurlencode($r['message'])?>">WhatsApp ↗</a><?php endif;endif;?> <?php if($awAdmin&&$r['status']==='pending'):?><form method="post"><?=$awHidden?><input type="hidden" name="aw_action" value="alert_review"><input type="hidden" name="alert_id" value="<?=$r['id']?>"><button>Mark reviewed</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div>
<?php elseif($awTab==='reports'):?>
<div class="aw-panel"><h2>Absence and lateness trends</h2><p>Attendance patterns from the last 30 days. Use these indicators to support students, not to make automatic disciplinary decisions.</p><div class="aw-scroll"><table class="aw-table"><tr><th>Learner</th><th>Absent</th><th>Late</th><th>Recorded days</th></tr><?php foreach(q("SELECT s.name, SUM(a.status='absent') absences,SUM(a.status='late') lates,COUNT(*) days_count FROM aw_period_attendance a JOIN students s ON s.id=a.student_id AND s.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.period_name='Daily' AND a.attendance_date>=DATE_SUB(CURDATE(),INTERVAL 30 DAY) GROUP BY a.student_id,s.name ORDER BY absences DESC,lates DESC LIMIT 100",[$tid])->fetchAll() as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['absences'])?></td><td><?=e($r['lates'])?></td><td><?=e($r['days_count'])?></td></tr><?php endforeach;?></table></div></div>
<?php elseif($awTab==='settings'):?>
<div class="aw-panel"><h2>Privacy and safeguarding controls</h2><p>Confidential counselling, safeguarding, sick bay and medication records are restricted to school administrators. Teachers may access attendance and non-confidential behaviour records.</p><div class="aw-warning">Open Communication → QR / NFC check-in to register scanner devices and issue student credentials. Parent alerts can be handed off to WhatsApp for manual sending. Never treat opening WhatsApp as confirmed delivery.</div></div>
<?php endif;?>
<?php endif;?></div>
<?php elseif($section==='audit'):?><h1>Audit Logs</h1><div class=card><table class=table><tr><th>Time</th><th>Action</th><th>Entity</th><th>Details</th></tr><?php foreach(q('SELECT * FROM audit_logs WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll() as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['action'])?></td><td><?=e($r['entity_type'])?></td><td><?=e($r['details'])?></td></tr><?php endforeach;?></table></div><?php else:?><h1><?=e($nav[$section]??ucwords($section))?></h1><div class=card><p class=muted>This module is included in the standalone schema and navigation. Its tenant-scoped records are ready for extension from the same authentication and database layer.</p></div><?php endif;?></div></main></div><script>(function(){const app=document.getElementById('app'),toggle=document.getElementById('toggle'),shade=document.getElementById('shade'),search=document.getElementById('navSearch');function close(){app.classList.remove('nav-open');toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{const v=app.classList.toggle('nav-open');toggle.setAttribute('aria-expanded',String(v))});shade.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.querySelectorAll('.group-title').forEach(btn=>btn.addEventListener('click',()=>{const group=btn.closest('.navgroup');group.classList.toggle('open');btn.setAttribute('aria-expanded',String(group.classList.contains('open')))}));search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();document.querySelectorAll('.navgroup').forEach(g=>{let visible=0;g.querySelectorAll('.navitem').forEach(a=>{const match=a.textContent.toLowerCase().includes(q);a.hidden=!match;a.style.display=match?'':'none';if(match)visible++});g.style.display=visible?'':'none';if(q)g.classList.add('open')})})})();</script><script>(function(){
const btn=document.getElementById('themeToggle');const label=document.getElementById('themeLabel');
function contrast(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))return '#ffffff';const c=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(x=>x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4));return (.2126*c[0]+.7152*c[1]+.0722*c[2])>.179?'#101828':'#ffffff'}
const st=getComputedStyle(document.documentElement);document.documentElement.style.setProperty('--accent-text',contrast(st.getPropertyValue('--accent').trim()));document.documentElement.style.setProperty('--highlight-text',contrast(st.getPropertyValue('--highlight').trim()));
function render(){if(label)label.textContent=document.documentElement.dataset.theme==='dark'?'Light mode':'Dark mode';if(btn)btn.setAttribute('aria-pressed',document.documentElement.dataset.theme==='dark'?'true':'false')}
if(btn)btn.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('schoolos-theme',next)}catch(e){}render()});render();
const upload=document.getElementById('schoolLogoInput');if(upload)upload.addEventListener('change',()=>{const file=upload.files&&upload.files[0],out=document.getElementById('schoolLogoPreview');if(!file||!out)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2097152){alert('Choose a PNG, JPG or WebP under 2 MB.');upload.value='';return;}const url=URL.createObjectURL(file),img=document.createElement('img');img.src=url;img.alt='Selected logo preview';img.style.cssText='max-height:76px;max-width:180px;object-fit:contain';img.onload=()=>URL.revokeObjectURL(url);out.replaceChildren(img)});
})();</script></body></html>
